window.TADABBUR_ZUMAR = {"_meta":{"description":"تدبّر سورة الزمر (٣٩) — سورةٌ مكّيّةٌ محورُها إخلاصُ الدينِ لله وحده والتحذيرُ من الشرك، وتقريرُ التوحيدِ بآياتِ الخلقِ والتدبير، والموازنةُ بين العالمِ والجاهلِ والمؤمنِ والكافر، وسَوقُ الناسِ إلى الجنّةِ والنارِ زمرًا. تُعرَف بسورةِ الزمرِ لذكرِ سَوقِ الفريقين زمرًا في آخرها. فيها آيةُ الرجاءِ العظمى «قل يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله»، وتمثيلُ حالِ القرآنِ «الله نزل أحسن الحديث كتابا متشابها مثاني»، ومشهدُ القيامةِ ونفخِ الصورِ ووضعِ الكتابِ ومجيءِ الأنبياءِ والشهداء، وختامُها بتسبيحِ الملائكةِ حافّين حولَ العرشِ وقضاءِ الله بالحقِّ وحمدِه ربِّ العالمين.","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":39,"name":"الزمر","total_ayahs":75,"audio":[],"passages":[{"title":"تنزيلُ الكتابِ والأمرُ بإخلاصِ الدين، ونفيُ الولد، وآياتُ الخلقِ والتدبير","range":[1,6],"theme":"أنّ القرآنَ منزّلٌ من الله العزيزِ الحكيمِ بالحق، والأمرُ بعبادةِ الله مخلصًا له الدين، وأنّ الدينَ الخالصَ لله وحده وإبطالُ شبهةِ التقرّبِ بالوسائط، وتنزيهُ الله عن الولدِ وأنه الواحدُ القهّار، وآياتُ خلقِ السماواتِ والأرضِ وتكويرِ الليلِ والنهارِ وتسخيرِ الشمسِ والقمر، وخلقِ الإنسانِ من نفسٍ واحدةٍ أطوارًا في ظلماتٍ ثلاث","verses":[{"n":1,"reflection":{"text":"«تنزيل الكتاب من الله العزيز الحكيم» — هذا القرآنُ منزّلٌ من الله العزيزِ الغالبِ الحكيمِ في خلقه وشرعه؛ ففي هذا تقريرُ مصدرِ القرآنِ الإلهيِّ وتعظيمُه؛ فعظّم القرآنَ لأنه من الله العزيزِ الحكيم، وتلقَّه بالتسليمِ والقبول، فما جاء من الله فهو حقٌّ وحكمة، فأقبل عليه بالتعظيمِ والاتّباع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ لأنه من الله العزيزِ الحكيم، وتلقّيه بالقبول."},"action":{"text":"عظّم القرآنَ في قلبك، فهو منزّلٌ من الله العزيزِ الغالبِ الذي لا يُقهَر، الحكيمِ في خلقه وأمره وشرعه «تنزيل الكتاب من الله العزيز الحكيم»؛ فمصدرُ القرآنِ إلهيٌّ عظيم؛ فما دام القرآنُ من الله العزيزِ الحكيم، فهو حقٌّ كلُّه، وحكمةٌ كلُّه، لا باطلَ فيه ولا عبث؛ فتلقَّه بالتسليمِ والقبولِ والتعظيم؛ وأقبل عليه بالتلاوةِ والتدبّرِ والعملِ والتحكيم؛ فمن عرف أنّ القرآنَ كلامُ الله عظّمه واتّبعه؛ فلا تعارض القرآنَ برأيٍ ولا هوًى؛ ولا تستهن بأمرٍ من أوامره أو نهيٍ من نواهيه؛ فهو من العزيزِ الذي عزّته توجب هيبته، الحكيمِ الذي حكمته توجب اتّباعه؛ فاجعل للقرآنِ في قلبك منزلته اللائقةَ به؛ فبتعظيمِ القرآنِ والعملِ به تُنال السعادةُ والهداية."}},{"n":2,"reflection":{"text":"«إنا أنزلنا إليك الكتاب بالحق فاعبد الله مخلصا له الدين» — إنا أنزلنا إليك الكتابَ بالحقِّ الثابت، فاعبد الله وحده مخلصًا له الطاعةَ والدين؛ ففي هذا الأمرُ بإخلاصِ العبادةِ لله؛ فأخلص دينك وعبادتك لله وحده، فالعبادةُ لا تُقبَل إلا بالإخلاص، فاجعل عملك كلَّه خالصًا لوجهِ الله، فالإخلاصُ روحُ العبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ والدينِ لله وحده."},"action":{"text":"اعلم أنّ الله أنزل الكتابَ بالحقِّ الثابتِ الذي لا ريبَ فيه، وأمر نبيَّه ومن اتّبعه أن يعبدوا الله وحده مخلصين له الطاعةَ والدين «إنا أنزلنا إليك الكتاب بالحق فاعبد الله مخلصا له الدين»؛ ففي هذا الأمرُ بإخلاصِ العبادةِ والدينِ لله وحده؛ فأخلص دينك وعبادتك ونيّتك لله وحده؛ فالعبادةُ لا تُقبَل إلا بشرطين: الإخلاصِ لله، والمتابعةِ لرسولِه ﷺ؛ فاجعل عملك كلَّه — صلاتك وصومك وصدقتك وذكرك — خالصًا لوجهِ الله، لا رياءً ولا سمعةً ولا طلبًا لعرضِ الدنيا؛ فالإخلاصُ روحُ العبادةِ ولبُّها؛ وما أُمِروا إلا ليعبدوا الله مخلصين له الدين؛ فراقب نيّتك في أعمالك؛ وطهّرها من شوائبِ الرياءِ وحظوظِ النفس؛ فمن أخلص لله قبل الله عمله، ومن راءى ردّه عليه؛ فاجعل الإخلاصَ همّك في كلِّ عمل؛ فبالإخلاصِ تُقبَل الأعمال، وتُرفَع الدرجات، ويُنال رضا الله."}},{"n":3,"reflection":{"text":"«ألا لله الدين الخالص والذين اتخذوا من دونه أولياء ما نعبدهم إلا ليقربونا إلى الله زلفى إن الله يحكم بينهم فيما هم فيه يختلفون إن الله لا يهدي من هو كاذب كفار» — ألا لله الطاعةُ الخالصةُ وحده، والمشركون يعبدون أولياءهم بزعمِ أنهم يقرّبونهم إلى الله، وسيحكم الله بينهم، ولا يهدي من هو كاذبٌ كفّار؛ ففي هذا إبطالُ حجّةِ الشركِ بالوسائط؛ فلا تتّخذ واسطةً بينك وبين الله في العبادة، بل اعبده مباشرةً مخلصًا، فالتقرّبُ بعبادةِ غيرِ الله شركٌ لا يقرّب بل يبعّد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"نبذُ الوسائطِ في العبادة، والتقرّبُ إلى الله بإخلاصِ العبادةِ له."},"action":{"text":"اعلم أنّ الدينَ الخالصَ من الشركِ حقٌّ لله وحده، وأنّ المشركين الذين اتّخذوا من دونِ الله أولياءَ يعبدونهم احتجّوا بأنهم ما يعبدونهم إلا ليقرّبوهم إلى الله زلفى ووسيلة، وأنّ الله سيحكم بينهم فيما يختلفون فيه، ولا يهدي من هو كاذبٌ في دعواه كفّارٌ لنعمِ الله «ألا لله الدين الخالص... ما نعبدهم إلا ليقربونا إلى الله زلفى...»؛ ففي هذا إبطالُ حجّةِ المشركين في اتّخاذِ الوسائطِ بينهم وبين الله؛ فهذه عينُ شبهةِ المشركين في كلِّ زمان: يعبدون الأولياءَ والصالحين والقبورَ بزعمِ التقرّبِ إلى الله بهم؛ فلا تتّخذ واسطةً بينك وبين الله في العبادةِ والدعاءِ والتقرّب؛ بل اعبد الله مباشرةً، وادعه وحده، وتقرّب إليه بطاعتِه لا بعبادةِ غيره؛ فالله قريبٌ يسمع دعاءك بلا واسطة؛ وإذا سألك عبادي عنّي فإني قريب؛ فالتقرّبُ بعبادةِ غيرِ الله شركٌ لا يقرّب من الله بل يبعّد عنه ويوجب النار؛ فأخلص عبادتك ودعاءك وتقرّبك لله وحده؛ ولا تجعل بينك وبينه وسيطًا؛ فالله لا يهدي الكاذبين الكفّار المشركين؛ فاحذر الشركَ ووسائله؛ وتقرّب إلى الله بالإخلاصِ والطاعة."}},{"n":4,"reflection":{"text":"«لو أراد الله أن يتخذ ولدا لاصطفى مما يخلق ما يشاء سبحانه هو الله الواحد القهار» — لو أراد الله ولدًا لاختار من خلقه ما يشاء، لكنه منزّهٌ عن ذلك، هو الله الواحدُ القهّار؛ ففي هذا تنزيهُ الله عن الولدِ وتقريرُ توحيده؛ فنزّه الله عن الولدِ والصاحبةِ والشريك، وعظّمه في قلبك، فهو الواحدُ القهّارُ الذي لا يحتاج إلى ولد، فأفرده بالتعظيمِ والعبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، وتعظيمُه الواحدَ القهّار."},"action":{"text":"اعلم أنّ الله ردّ على من زعم له ولدًا بأبلغِ ردّ: لو أراد الله أن يتّخذ ولدًا — على سبيلِ الفرضِ المحال — لاختار من خلقه ما يشاء، لكنه منزّهٌ عن ذلك كلِّه؛ فهو الله الواحدُ الأحدُ القهّارُ لكلِّ شيء «لو أراد الله أن يتخذ ولدا لاصطفى مما يخلق ما يشاء سبحانه هو الله الواحد القهار»؛ ففي هذا تنزيهُ الله عن الولد، وتقريرُ توحيده وقهره؛ فالولدُ يكون عن حاجةٍ ومشابهةٍ ومجانسة، والله الغنيُّ المنزّهُ عن ذلك؛ فنزّه الله عن الولدِ والصاحبةِ والشريكِ والند؛ فهو الواحدُ في ذاته وصفاته، القهّارُ الذي قهر كلَّ شيءٍ وخضع له كلُّ شيء؛ فكيف يكون له ولدٌ وهو خالقُ كلِّ شيءٍ وقاهره؟ فعظّم الله في قلبك، ونزّهه عن كلِّ ما لا يليق بجلاله؛ فأفرده بالتعظيمِ والعبادةِ والتوحيد؛ فمن عرف أنّ الله الواحدُ القهّار نزّهه عن الولدِ والشريك، وأخلص له العبادة؛ فسبحان الله عمّا يشركون، وتعالى عمّا يقولون علوًّا كبيرًا."}},{"n":5,"reflection":{"text":"«خلق السماوات والأرض بالحق يكور الليل على النهار ويكور النهار على الليل وسخر الشمس والقمر كل يجري لأجل مسمى ألا هو العزيز الغفار» — خلق السماواتِ والأرضَ بالحقِّ والحكمة، يُدخِل الليلَ على النهارِ والنهارَ على الليل، وسخّر الشمسَ والقمرَ يجريان إلى أجلٍ محدّد، هو العزيزُ الغفّار؛ ففي هذا آياتُ القدرةِ على التوحيد؛ فتأمّل في خلقِ السماواتِ وتعاقبِ الليلِ والنهارِ وجريِ الشمسِ والقمر، فمن دبّر هذا يستحقّ العبادةَ وحده، فوحّد المدبّرَ العظيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في آياتِ الخلقِ والتدبيرِ لتوحيدِ المدبّر."},"action":{"text":"تأمّل آياتِ قدرةِ الله ووحدانيّته: خلق السماواتِ والأرضَ بالحقِّ والحكمةِ لا عبثًا، وهو يُكوّر الليلَ على النهارِ والنهارَ على الليل — أي يُدخِل كلًّا منهما على الآخرِ ويلفّه عليه في تعاقبٍ دائم، وسخّر الشمسَ والقمرَ يجريان في أفلاكهما إلى أجلٍ مسمًّى هو يومُ القيامة، وهو العزيزُ الغالبُ الغفّارُ لمن تاب «خلق السماوات والأرض بالحق... كل يجري لأجل مسمى ألا هو العزيز الغفار»؛ ففي هذه الآياتِ العظيمةِ دلائلُ على قدرةِ الله ووحدانيّته واستحقاقِه للعبادة؛ فتأمّل في خلقِ السماواتِ والأرض، وفي تعاقبِ الليلِ والنهارِ ودقّةِ نظامهما، وفي جريِ الشمسِ والقمرِ بحسابٍ محكم؛ فمن دبّر هذا الكونَ العظيمَ بهذه الحكمةِ والإتقانِ يستحقّ العبادةَ وحده؛ فوحّد المدبّرَ العظيمَ الخالقَ لكلِّ شيء؛ فالتفكّرُ في خلقِ الله يورث تعظيمَه ومحبّته وتوحيده؛ إنّ في خلقِ السماواتِ والأرضِ واختلافِ الليلِ والنهارِ لآياتٍ لأولي الألباب؛ فاجعل نظرك في الكونِ عبادةً تزيدك إيمانًا وتوحيدًا؛ فهو العزيزُ في انتقامه، الغفّارُ في رحمته؛ فارجُ مغفرته، واخشَ عزّته، ووحّده في ربوبيّته وألوهيّته."}},{"n":6,"reflection":{"text":"«خلقكم من نفس واحدة ثم جعل منها زوجها وأنزل لكم من الأنعام ثمانية أزواج يخلقكم في بطون أمهاتكم خلقا من بعد خلق في ظلمات ثلاث ذلكم الله ربكم له الملك لا إله إلا هو فأنى تصرفون» — خلقكم من آدمَ ثم جعل منه زوجه، وخلق لكم من الأنعامِ أصنافًا، ويخلقكم في بطونِ أمهاتكم أطوارًا في ظلماتٍ ثلاث، ذلكم الله ربّكم له الملكُ لا إله إلا هو، فكيف تُصرَفون عن عبادته؟ ففي هذا آياتُ الخلقِ في الأنفسِ على التوحيد؛ فتأمّل في خلقك أطوارًا في بطنِ أمك، فمن خلقك هكذا هو ربّك المستحقُّ للعبادة، فوحّده ولا تُصرَف عنه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في خلقِ النفسِ أطوارًا لتوحيدِ الخالق."},"action":{"text":"تأمّل آياتِ الله في خلقك: خلقكم من نفسٍ واحدةٍ هي آدم، ثم جعل منها زوجها حواء، وأنزل لكم من الأنعامِ ثمانيةَ أزواجٍ تنتفعون بها، ويخلقكم في بطونِ أمهاتكم خلقًا بعد خلقٍ — نطفةً ثم علقةً ثم مضغة — في ظلماتٍ ثلاث: ظلمةِ البطنِ والرحمِ والمشيمة؛ ذلكم الله ربّكم له الملكُ كلُّه، لا إله إلا هو، فكيف تُصرَفون عن عبادته إلى عبادةِ غيره؟ «خلقكم من نفس واحدة... يخلقكم في بطون أمهاتكم خلقا من بعد خلق في ظلمات ثلاث ذلكم الله ربكم له الملك لا إله إلا هو فأنى تصرفون»؛ ففي هذا آياتُ الخلقِ في الأنفسِ الدالّةُ على التوحيد؛ فتأمّل في خلقك أطوارًا في بطنِ أمك، وأنت لا تملك لنفسك شيئًا؛ فمن خلقك هذا الخلقَ البديعَ في تلك الظلماتِ هو ربّك المالكُ المدبّرُ المستحقُّ للعبادةِ وحده؛ فوحّده، ولا تنصرف عن عبادته إلى عبادةِ من لا يخلق ولا يملك؛ فكيف تعبد غيرَ خالقك ومالكك ومدبّرك؟ فأفرد الله بالعبادةِ كما تفرّد بالخلقِ والملك؛ فمن تأمّل خلقَ الله له عرف ربه ووحّده وأخلص له العبادة."}}]},{"title":"غنى الله عن الخلق، وتقلّبُ الإنسان، وتفاضلُ القانتِ والعالم، ووصيّةُ التقوى والصبر","range":[7,10],"theme":"أنّ الله غنيٌّ عن خلقه لا يرضى لهم الكفرَ ويرضى الشكر، وأنّ كلَّ نفسٍ تحمل وزرها، وتقلّبُ الإنسانِ يدعو في الضرِّ وينسى في النعمة، والموازنةُ بين الكافرِ والقانتِ آناءَ الليل، وأنّ العالمين لا يستوون مع الجاهلين، ونداءُ المؤمنين بالتقوى والإحسانِ والصبرِ الذي يُوفّى أجره بغيرِ حساب","verses":[{"n":7,"reflection":{"text":"«إن تكفروا فإن الله غني عنكم ولا يرضى لعباده الكفر وإن تشكروا يرضه لكم ولا تزر وازرة وزر أخرى ثم إلى ربكم مرجعكم فينبئكم بما كنتم تعملون إنه عليم بذات الصدور» — إن تكفروا فالله غنيٌّ عنكم، ولا يرضى الكفرَ لعباده، وإن تشكروا يرضَ الشكرَ لكم، ولا تحمل نفسٌ وزرَ أخرى، ثم إلى ربّكم مرجعكم فيخبركم بأعمالكم، إنه عليمٌ بما في الصدور؛ ففي هذا بيانُ غنى الله ومحبّتِه الشكر؛ فاشكر الله لينفعك شكرك، واعلم أنّ كفرك لا يضرّ الله، فالطاعةُ لك والمعصيةُ عليك، فبادر بالشكرِ والطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشكرُ لله لينفع العبدَ، وإدراكُ غنى الله عن الخلق."},"action":{"text":"اعلم أنّ الله غنيٌّ عن خلقه: إن تكفروا فإنّ الله غنيٌّ عنكم لا يضرّه كفركم، لكنه لا يرضى الكفرَ لعباده لأنه سببُ شقائهم، وإن تشكروا يرضَ الشكرَ لكم لأنه سببُ سعادتكم، ولا تحمل نفسٌ ذنبَ أخرى، ثم إلى ربّكم مرجعكم فينبّئكم بما عملتم، إنه عليمٌ بما تكنّه الصدور «إن تكفروا فإن الله غني عنكم ولا يرضى لعباده الكفر وإن تشكروا يرضه لكم...»؛ ففي هذا بيانُ غنى الله المطلقِ عن خلقه، ومحبّتِه لشكرِ عباده رحمةً بهم؛ فاشكر الله على نعمه، فإنّ شكرك ينفعك أنت لا الله؛ ومن شكر فإنما يشكر لنفسه؛ واعلم أنّ كفرك ومعصيتك لا يضرّان الله شيئًا، وإنما يضرّانك أنت؛ فالطاعةُ لك ونفعها يعود عليك، والمعصيةُ عليك وضررها يعود عليك؛ فبادر بالشكرِ والطاعةِ لتنال رضا الله وثوابه؛ واعلم أنك مرجعك إلى الله، فينبّئك بعملك ويجازيك عليه؛ فهو عليمٌ بما في صدرك من النيّاتِ والخفايا؛ فراقب الله في سرّك وعلنك؛ واعلم أنّ كلَّ نفسٍ تحمل وزرها لا وزرَ غيرها؛ فاعمل لنفسك، واشكر لربك، واستعدّ للقائه."}},{"n":8,"reflection":{"text":"«وإذا مس الإنسان ضر دعا ربه منيبا إليه ثم إذا خوله نعمة منه نسي ما كان يدعو إليه من قبل وجعل لله أندادا ليضل عن سبيله قل تمتع بكفرك قليلا إنك من أصحاب النار» — إذا أصاب الإنسانَ ضرٌّ دعا ربه منيبًا، فإذا أعطاه نعمةً نسي دعاءه السابقَ وجعل لله أندادًا، قل له: تمتّع بكفرك قليلًا، إنك من أهلِ النار؛ ففي هذا ذمُّ تقلّبِ الإنسانِ وكفرِه عند النعمة؛ فاحذر أن تلجأ إلى الله في الشدّةِ وتنساه في الرخاء، بل اذكر الله في الرخاءِ كما تدعوه في الشدّة، فالوفاءُ في العبوديةِ في الحالين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من نسيانِ الله في الرخاء بعد اللجوءِ إليه في الشدّة."},"action":{"text":"تأمّل ذمَّ الله لتقلّبِ الإنسانِ الجاحد: إذا مسّه ضرٌّ أو مرضٌ أو شدّةٌ دعا ربه منيبًا إليه راجعًا مخلصًا، فإذا كشف الله ضرّه وأعطاه نعمةً منه نسي دعاءه السابقَ الذي كان يتضرّع به، وجعل لله أندادًا وشركاءَ يعبدهم ويدعوهم ليُضلّ غيره عن سبيلِ الله؛ فقيل له: تمتّع بكفرك قليلًا في الدنيا، إنك من أصحابِ النار «وإذا مس الإنسان ضر دعا ربه منيبا إليه ثم إذا خوله نعمة منه نسي ما كان يدعو إليه من قبل وجعل لله أندادا...»؛ ففي هذا ذمُّ تقلّبِ الإنسانِ وجحودِه وكفرِه عند النعمةِ بعد إخلاصِه عند الشدّة؛ فاحذر أن تكون ممّن يلجأ إلى الله ويخلص له في الشدّةِ والضرّ، ثم ينساه ويعرض عنه في الرخاءِ والعافية؛ بل كن وفيًّا في عبوديتك لله في الحالين؛ فاذكر الله في رخائك كما تدعوه في شدّتك؛ فمن ذكر الله في الرخاءِ ذكره الله في الشدّة؛ فلا تكن ممّن يعرف الله في الضرّاءِ وينساه في السرّاء؛ فالوفاءُ في العبوديةِ أن تعبد الله وتذكره وتشكره في الشدّةِ والرخاء، والعسرِ واليسر؛ فراقب نفسك: هل تنسى الله عند النعمة؟ فتب من ذلك، والزم ذكره وشكره وطاعته دائمًا؛ فالمؤمنُ الوفيُّ يعبد الله في كلِّ حال."}},{"n":9,"reflection":{"text":"«أمن هو قانت آناء الليل ساجدا وقائما يحذر الآخرة ويرجو رحمة ربه قل هل يستوي الذين يعلمون والذين لا يعلمون إنما يتذكر أولو الألباب» — أهذا الكافرُ خيرٌ أم من هو مطيعٌ قانتٌ ساعاتِ الليلِ ساجدًا وقائمًا يخاف الآخرةَ ويرجو رحمةَ ربه؟ قل هل يستوي العالمون والجاهلون؟ إنما يتذكّر أصحابُ العقول؛ ففي هذا مدحُ القانتِ العالمِ وتفضيلُه؛ فكن من القانتين العابدين العالمين، فالعلمُ والعبادةُ يرفعان صاحبهما، فاجمع بين قيامِ الليلِ وطلبِ العلم، وبين الخوفِ والرجاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين قيامِ الليلِ والعلمِ والخوفِ والرجاء."},"action":{"text":"تأمّل موازنةَ الله بين الكافرِ الجاحدِ والمؤمنِ القانت: أهذا الجاحدُ خيرٌ أم من هو قانتٌ مطيعٌ خاشعٌ ساعاتِ الليلِ ساجدًا وقائمًا في صلاته، يحذر عذابَ الآخرةِ ويرجو رحمةَ ربه؟ قل هل يستوي الذين يعلمون والذين لا يعلمون؟ لا يستويان، إنما يتذكّر ويتّعظ أولو الألباب أصحابُ العقولِ السليمة «أمن هو قانت آناء الليل ساجدا وقائما يحذر الآخرة ويرجو رحمة ربه قل هل يستوي الذين يعلمون والذين لا يعلمون...»؛ ففي هذا مدحُ القانتِ العابدِ العالم، وتفضيلُه على الجاهلِ الغافل؛ فكن من القانتين العابدين المصلّين بالليل، العالمين بربهم ودينهم؛ فالعلمُ النافعُ والعبادةُ الخالصةُ يرفعان صاحبهما عند الله وعند الناس؛ فاجمع بين قيامِ الليلِ والسجودِ والخشوع، وبين طلبِ العلمِ النافعِ والعملِ به؛ واجمع في قلبك بين الحذرِ من الآخرةِ والرجاءِ لرحمةِ الله؛ فالخوفُ يمنعك من المعاصي، والرجاءُ يحملك على الطاعة؛ فقُم من الليلِ ولو يسيرًا، واسجد لربك، وادعه خائفًا راجيًا؛ وتعلّم العلمَ الذي يقرّبك من الله؛ فلا يستوي العالمُ والجاهل، ولا القانتُ والغافل؛ فاطلب الرفعةَ بالعلمِ والعبادةِ والقنوتِ لله؛ فمن جمع بين العلمِ والعملِ والقيامِ فقد فاز."}},{"n":10,"reflection":{"text":"«قل يا عباد الذين آمنوا اتقوا ربكم للذين أحسنوا في هذه الدنيا حسنة وأرض الله واسعة إنما يوفى الصابرون أجرهم بغير حساب» — قل يا عبادي المؤمنين اتّقوا ربّكم، للذين أحسنوا في الدنيا حسنةٌ، وأرضُ الله واسعةٌ فهاجروا إن مُنِعتم، إنما يُوفّى الصابرون أجرهم بلا حساب؛ ففي هذا الأمرُ بالتقوى وبشارةُ المحسنين والصابرين؛ فاتّق الله وأحسن، واصبر على الطاعةِ والبلاء، فأجرُ الصابرين بلا حساب، فاجعل الصبرَ زادك لتنال الأجرَ العظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى والإحسانُ والصبر، فأجرُ الصابرين بلا حساب."},"action":{"text":"تأمّل نداءَ الله لعباده المؤمنين: قل يا عبادي الذين آمنوا اتّقوا ربّكم بامتثالِ أمره واجتنابِ نهيه، فللذين أحسنوا في هذه الدنيا حسنةٌ في الدنيا والآخرة، وأرضُ الله واسعةٌ فهاجروا فيها إن مُنِعتم من عبادةِ ربكم في أرض، إنما يُوفّى الصابرون أجرهم بغيرِ حسابٍ ولا حدٍّ ولا عدّ «قل يا عباد الذين آمنوا اتقوا ربكم... إنما يوفى الصابرون أجرهم بغير حساب»؛ ففي هذا الأمرُ بالتقوى، وبشارةُ المحسنين بالحسنة، وبشارةُ الصابرين بالأجرِ العظيمِ بلا حساب؛ فاتّق الله في سرّك وعلنك؛ وأحسن في عبادتك ومعاملتك؛ واصبر على طاعةِ الله، وعن معصيته، وعلى أقداره؛ فالصبرُ مفتاحُ الأجرِ العظيم؛ فما من عملٍ يُجازى صاحبه إلا بقدرٍ معلومٍ إلا الصبر، فإنّ الصابرين يُوفّون أجرهم بغيرِ حساب؛ فاجعل الصبرَ زادك في كلِّ أمرك؛ واصبر على تكاليفِ الدينِ ومشاقّه، وعلى المصائبِ والبلايا، وعن الشهواتِ والمعاصي؛ فأجرُ الصابرين لا يُحَدّ؛ فإن ضاقت بك أرضٌ عن دينك فأرضُ الله واسعة؛ فلا تؤثر البقاءَ في مكانٍ يُفتَن فيه دينك؛ فاتّق الله، وأحسن، واصبر، وهاجر إن لزم؛ فالتقوى والإحسانُ والصبرُ سبيلُ الفوزِ والأجرِ الجزيل."}}]},{"title":"الأمرُ بإخلاصِ العبادةِ والخوفِ من العذاب، وبشرى المنيبين المستمعين أحسنَ القول","range":[11,20],"theme":"أمرُ النبيِّ بعبادةِ الله مخلصًا وأن يكون أوّلَ المسلمين وخوفِه من عذابِ يومٍ عظيم، وأنّ الخاسرين من خسروا أنفسهم وأهليهم، والتخويفُ بظللِ النارِ ليتّقيَ العباد، وبشرى من اجتنبوا الطاغوتَ وأنابوا إلى الله واستمعوا القولَ فاتّبعوا أحسنه، وأنّ الهدايةَ بيدِ الله، وأنّ للمتّقين غرفًا عاليةً في الجنّة","verses":[{"n":11,"reflection":{"text":"«قل إني أمرت أن أعبد الله مخلصا له الدين» — قل يا محمدُ: إني أُمِرت أن أعبد الله مخلصًا له الطاعةَ والدين؛ ففي هذا تقريرُ الإخلاصِ والاقتداءُ بالنبيِّ فيه؛ فأخلص عبادتك لله كما أُمِر النبيُّ بالإخلاص، فالإخلاصُ أمرُ الله لرسولِه ولكلِّ عبد، فاجعل عبادتك خالصةً لله وحده اقتداءً بنبيّك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله اقتداءً بأمرِ النبيّ."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يعلنه: قل إني أُمِرت من ربي أن أعبد الله وحده مخلصًا له الطاعةَ والدين، لا أشرك به شيئًا «قل إني أمرت أن أعبد الله مخلصا له الدين»؛ ففي هذا تقريرُ الإخلاصِ وأنه أمرُ الله لرسولِه ولكلِّ عبد؛ فأخلص عبادتك لله وحده كما أُمِر النبيُّ ﷺ بالإخلاص؛ فإذا كان النبيُّ — أكملُ الخلقِ — مأمورًا بالإخلاص، فأنت أولى بلزومه؛ فالإخلاصُ فرضٌ على كلِّ عبد؛ وما أُمِروا إلا ليعبدوا الله مخلصين له الدين؛ فاجعل عبادتك — صلاتك وصومك وحجّك وذكرك وسائرَ عملك — خالصةً لوجهِ الله وحده؛ اقتداءً بنبيّك الذي أُمِر بالإخلاص؛ فلا تصرف شيئًا من العبادةِ لغيرِ الله؛ ولا تشُب عملك برياءٍ أو سمعةٍ أو طلبِ دنيا؛ فالإخلاصُ روحُ العبادة، وبه تُقبَل الأعمال؛ فراقب نيّتك، وطهّرها لله؛ فمن أخلص لله كما أخلص نبيُّه فقد اهتدى؛ فاجعل الإخلاصَ شعارك في كلِّ عبادة؛ فبالإخلاصِ والمتابعةِ تُقبَل الأعمال وتُرفَع الدرجات."}},{"n":12,"reflection":{"text":"«وأمرت لأن أكون أول المسلمين» — وأُمِرت لأكون أوّلَ المستسلمين لله من هذه الأمّة؛ ففي هذا مبادرةُ النبيِّ إلى الإسلامِ والطاعة؛ فبادر إلى الإسلامِ والطاعةِ والانقيادِ لله، وكن سبّاقًا إلى الخير، فالمبادرةُ إلى الطاعةِ من صفاتِ السابقين، فاجعل نفسك في مقدّمةِ المستسلمين لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ إلى الإسلامِ والطاعةِ والانقيادِ لله."},"action":{"text":"تأمّل ما أُمِر به النبيُّ ﷺ: وأُمِرت لأن أكون أوّلَ المسلمين المستسلمين لله من هذه الأمّة، أسبقهم إلى الإسلامِ والطاعةِ والانقياد «وأمرت لأن أكون أول المسلمين»؛ ففي هذا مبادرةُ النبيِّ ﷺ إلى الإسلامِ والطاعةِ وسبقُه إليها؛ فكان أوّلَ من امتثل ما يأمر به غيره؛ فبادر أنت إلى الإسلامِ والطاعةِ والانقيادِ لله؛ وكن سبّاقًا إلى الخيراتِ لا متأخّرًا؛ فالسابقون السابقون أولئك المقرّبون؛ فاجعل نفسك في مقدّمةِ المستسلمين لله، المبادرين إلى طاعته؛ فلا تتأخّر عن خيرٍ تقدر عليه؛ ولا تكن ممّن يأمر بالبرِّ ولا يبادر إليه؛ بل كن أوّلَ العاملين بما تعلم، أوّلَ المستجيبين لأمرِ الله؛ فالقدوةُ الصالحةُ تبدأ بنفسها؛ فسارعوا إلى مغفرةٍ من ربكم؛ وسابقوا إلى الخيرات؛ فمن بادر إلى الطاعةِ وسبق إليها نال المنزلةَ الرفيعة؛ فاجعل شأنك المسارعةَ والمبادرةَ والسبقَ إلى كلِّ خير؛ فبالمبادرةِ إلى الإسلامِ والطاعةِ تكون من السابقين المقرّبين."}},{"n":13,"reflection":{"text":"«قل إني أخاف إن عصيت ربي عذاب يوم عظيم» — قل إني أخاف إن عصيتُ ربي عذابَ يومٍ عظيمٍ (يومِ القيامة)؛ ففي هذا تعليمُ الخوفِ من عذابِ الله؛ فاخشَ عذابَ الله واحذر معصيته، فإذا كان النبيُّ يخاف العذابَ لو عصى، فأنت أولى بالخوفِ والحذر، فاجعل خوفَ العذابِ حاجزًا لك عن المعاصي.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من عذابِ الله، وجعلُه حاجزًا عن المعاصي."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يقوله: قل إني أخاف إن عصيتُ ربي فيما أمرني به من التوحيدِ والإخلاصِ عذابَ يومٍ عظيمِ الهولِ والشأن، وهو يومُ القيامة «قل إني أخاف إن عصيت ربي عذاب يوم عظيم»؛ ففي هذا تعليمُ الخوفِ من عذابِ الله والحذرِ من معصيته؛ فإذا كان النبيُّ ﷺ — المعصومُ المغفورُ له — يخاف العذابَ لو عصى ربه، فأنت أيها المذنبُ المفرّطُ أولى بالخوفِ والحذر؛ فاخشَ عذابَ الله، واحذر معصيته؛ فاجعل خوفَ العذابِ حاجزًا لك عن كلِّ معصية؛ فمن خاف عذابَ الله اجتنب أسبابه؛ فالخوفُ من الله سائقٌ إلى الطاعة، زاجرٌ عن المعصية؛ ولمن خاف مقامَ ربه جنّتان؛ فاجعل في قلبك خوفًا من الله يمنعك من الحرام؛ ولا تأمن مكرَ الله ولا عذابه؛ فلا يأمن مكرَ الله إلا القومُ الخاسرون؛ فاعبد الله خائفًا راجيًا؛ فبالخوفِ تجتنب المعاصي، وبالرجاءِ تُقبِل على الطاعات؛ فاجعل خوفَ عذابِ اليومِ العظيمِ رقيبًا على أعمالك؛ فمن خاف اليومَ العظيمَ استعدّ له بالطاعةِ واجتنابِ المعصية."}},{"n":14,"reflection":{"text":"«قل الله أعبد مخلصا له ديني» — قل: الله وحده أعبد مخلصًا له ديني وطاعتي؛ ففي هذا تأكيدُ إفرادِ الله بالعبادةِ والإخلاصِ له؛ فأفرد الله بالعبادةِ وأخلص له دينك، فلا تعبد سواه ولا تشرك به، فالعبادةُ حقُّ الله وحده، فاجعلها كلَّها خالصةً له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادةِ وإخلاصُ الدينِ له."},"action":{"text":"تأمّل تأكيدَ النبيِّ ﷺ لإخلاصه: قل الله وحده أعبد مخلصًا له ديني وطاعتي وعبادتي، لا أشرك به أحدًا «قل الله أعبد مخلصا له ديني»؛ ففي هذا تأكيدُ إفرادِ الله بالعبادةِ والإخلاصِ له بعد الأمرِ به؛ فأفرد الله بالعبادةِ وحده؛ وأخلص له دينك وطاعتك وعملك؛ فلا تعبد سواه، ولا تشرك به شيئًا في عبادتك؛ فالعبادةُ بجميعِ أنواعها — الدعاءِ والخوفِ والرجاءِ والتوكّلِ والذبحِ والنذرِ والصلاةِ — حقٌّ خالصٌ لله وحده؛ فاجعلها كلَّها خالصةً له؛ فمن صرف شيئًا منها لغيرِ الله فقد أشرك؛ فوحّد الله في عبادتك، وأخلص له دينك؛ فالتوحيدُ والإخلاصُ أصلُ الدينِ وأساسه؛ فراقب عبادتك أن تكون خالصةً لله، بريئةً من الشركِ صغيرِه وكبيره؛ فاعبد الله وحده مخلصًا، كما أعلن نبيُّك؛ فبالتوحيدِ والإخلاصِ تُقبَل العبادةُ ويُنال رضا الله."}},{"n":15,"reflection":{"text":"«فاعبدوا ما شئتم من دونه قل إن الخاسرين الذين خسروا أنفسهم وأهليهم يوم القيامة ألا ذلك هو الخسران المبين» — فاعبدوا ما شئتم من دونِ الله (تهديدًا)، قل: إنّ الخاسرين حقًّا الذين خسروا أنفسهم وأهليهم يومَ القيامة، ألا ذلك هو الخسرانُ المبين؛ ففي هذا بيانُ حقيقةِ الخسران؛ فاحذر الخسرانَ الأكبرَ: خسرانَ النفسِ يومَ القيامة، فاعمل لنجاةِ نفسك وأهلك، فالخاسرُ من خسر نفسه في النار، لا من خسر مالَ الدنيا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من خسرانِ النفسِ يومَ القيامة، والعملُ لنجاتِها."},"action":{"text":"تأمّل تهديدَ الله للمشركين وبيانَ حقيقةِ الخسران: فاعبدوا ما شئتم من دونِ الله — تهديدٌ ووعيد، لا إباحة — قل إنّ الخاسرين حقًّا هم الذين خسروا أنفسهم وأهليهم يومَ القيامة، بأن أوردوها النارَ وحُرِموا نعيمَ الجنّة، ألا ذلك هو الخسرانُ الواضحُ البيّن «فاعبدوا ما شئتم من دونه قل إن الخاسرين الذين خسروا أنفسهم وأهليهم يوم القيامة ألا ذلك هو الخسران المبين»؛ ففي هذا بيانُ حقيقةِ الخسرانِ الأكبر؛ فليس الخاسرُ من خسر مالًا أو تجارةً في الدنيا، بل الخاسرُ حقًّا من خسر نفسه وأهله يومَ القيامةِ بدخولِ النار؛ فاحذر هذا الخسرانَ المبين؛ واعمل لنجاةِ نفسك وأهلك من النار؛ يا أيها الذين آمنوا قوا أنفسكم وأهليكم نارًا؛ فاجتهد في هدايةِ نفسك أولًا بالإيمانِ والتوحيدِ والطاعة؛ ثم في هدايةِ أهلك بالتعليمِ والنصحِ والقدوة؛ فالخسارةُ الحقيقيةُ في الآخرةِ لا في الدنيا؛ فمن ربح الدنيا وخسر آخرته فهو الخاسر؛ فاعمل للربحِ الحقيقي: نجاةِ نفسك وأهلك يومَ القيامة؛ فبادر بالتوحيدِ والطاعةِ والدعوةِ إلى الله؛ فبها تنجو أنت وأهلك من الخسرانِ المبين."}},{"n":16,"reflection":{"text":"«لهم من فوقهم ظلل من النار ومن تحتهم ظلل ذلك يخوف الله به عباده يا عباد فاتقون» — لهم من فوقهم أطباقٌ من النارِ ومن تحتهم أطباق، بذلك يخوّف الله عباده ليتّقوه، يا عبادي فاتّقون؛ ففي هذا التخويفُ بالنارِ ليتّقيَ العباد؛ فاتّق الله واحذر النارَ التي تحيط بأهلها، فتذكّرُ النارِ يبعث على التقوى، فاجعل خوفَ النارِ حافزًا لك على تقوى الله وطاعته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقوى الله والحذرُ من النار، وجعلُ خوفِها حافزًا للطاعة."},"action":{"text":"تأمّل تصويرَ الله لعذابِ الكافرين: لهم من فوقهم أطباقٌ وظللٌ من النارِ تغشاهم، ومن تحتهم أطباقٌ وفرشٌ من النار، فهم محاطون بها من كلِّ جانب؛ بذلك العذابِ يخوّف الله عباده ليحذروه ويتّقوه؛ يا عبادي فاتّقون واحذروا عذابي «لهم من فوقهم ظلل من النار ومن تحتهم ظلل ذلك يخوف الله به عباده يا عباد فاتقون»؛ ففي هذا التخويفُ بالنارِ رحمةً بالعبادِ ليتّقوا؛ فاتّق الله واحذر النارَ التي تحيط بأهلها من فوقهم ومن تحتهم؛ فتذكّرُ النارِ وعذابها يبعث القلبَ على التقوى والطاعة؛ فاجعل خوفَ النارِ حافزًا لك على تقوى الله واجتنابِ معاصيه؛ فاتّقوا النارَ التي وقودها الناسُ والحجارة؛ فمن خاف النارَ اتّقى الله واجتنب أسبابها؛ فالتخويفُ بالنارِ من رحمةِ الله بعباده ليحملهم على التقوى؛ فاستجب لنداءِ ربك: يا عبادي فاتّقون؛ واجعل التقوى شعارك ولباسك؛ فمن اتّقى الله وقاه من النار؛ فبادر بالتقوى والطاعةِ واجتنابِ المعاصي؛ فبها تنجو من النارِ التي حذّرك الله منها؛ فالتقوى حصنٌ من عذابِ الله."}},{"n":17,"reflection":{"text":"«والذين اجتنبوا الطاغوت أن يعبدوها وأنابوا إلى الله لهم البشرى فبشر عباد» — والذين اجتنبوا عبادةَ الطاغوتِ (كلِّ معبودٍ سوى الله) ورجعوا إلى الله بالتوحيدِ والطاعة، لهم البشرى، فبشّر عبادي؛ ففي هذا بشارةُ المجتنبين للشركِ المنيبين إلى الله؛ فاجتنب عبادةَ كلِّ ما سوى الله، وأنب إليه بالتوحيدِ والطاعة، لتنال البشرى، فالنجاةُ في اجتنابِ الطاغوتِ والإنابةِ إلى الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الطاغوتِ والإنابةُ إلى الله لنيلِ البشرى."},"action":{"text":"تأمّل بشارةَ الله للموحّدين: والذين اجتنبوا الطاغوتَ — وهو كلُّ ما عُبِد من دونِ الله من صنمٍ أو قبرٍ أو شيطانٍ أو هوًى — أن يعبدوها، وأنابوا إلى الله بالتوحيدِ والتوبةِ والطاعة، لهم البشرى بالجنّةِ ورضوانِ الله، فبشّر عبادي بذلك «والذين اجتنبوا الطاغوت أن يعبدوها وأنابوا إلى الله لهم البشرى فبشر عباد»؛ ففي هذا بشارةُ المجتنبين للشركِ المنيبين إلى الله؛ فالنجاةُ والبشرى مبنيّتان على أمرين: اجتنابِ عبادةِ الطاغوت، والإنابةِ إلى الله؛ فاجتنب عبادةَ كلِّ ما سوى الله؛ فلا تعبد صنمًا ولا قبرًا ولا وليًّا ولا هوًى ولا شيطانًا؛ واكفر بالطاغوتِ كلِّه؛ فمن يكفر بالطاغوتِ ويؤمن بالله فقد استمسك بالعروةِ الوثقى؛ وأنب إلى الله بالتوحيدِ والتوبةِ والطاعةِ والرجوعِ إليه في كلِّ أمر؛ فمن اجتنب الطاغوتَ وأناب إلى الله فله البشرى في الدنيا والآخرة؛ فحقّق هذين الأصلين: البراءةَ من الشرك، والإنابةَ إلى الله؛ فبهما تكون من عبادِ الله المبشَّرين؛ فاجعل توحيدك خالصًا، وإنابتك دائمة؛ فبذلك تفوز بالبشرى والنجاة."}},{"n":18,"reflection":{"text":"«الذين يستمعون القول فيتبعون أحسنه أولئك الذين هداهم الله وأولئك هم أولو الألباب» — الذين يستمعون القولَ فيتّبعون أحسنه وأصوبه، أولئك هداهم الله وهم أصحابُ العقول؛ ففي هذا مدحُ من يتحرّى أحسنَ القولِ ويتّبعه؛ فتحرَّ أحسنَ القولِ وأصوبَه فاتّبعه، ولا تتّبع كلَّ ما يُقال، فالعاقلُ من يميّز الأحسنَ فيتّبعه، فاطلب الحقَّ واتّبع أحسنه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحرّي أحسنِ القولِ واتّباعُه، وتمييزُ الحقِّ من الباطل."},"action":{"text":"تأمّل مدحَ الله لعباده المهتدين: الذين يستمعون القولَ — القرآنَ وغيره — فيتّبعون أحسنه وأصوبه وأنفعه، فيميّزون الحقَّ من الباطلِ والأصوبَ من غيره، أولئك الذين هداهم الله للحق، وأولئك هم أولو الألبابِ أصحابُ العقولِ الراجحة «الذين يستمعون القول فيتبعون أحسنه أولئك الذين هداهم الله وأولئك هم أولو الألباب»؛ ففي هذا مدحُ من يتحرّى أحسنَ القولِ وأصوبه فيتّبعه؛ فتحرَّ أحسنَ القولِ وأصوبه وأنفعه فاتّبعه؛ ولا تتّبع كلَّ ما يُقال بلا تمييزٍ ولا تدبّر؛ بل استمع الأقوال، وزِنها بميزانِ الحقِّ والوحي، ثم اتّبع أحسنها؛ فالعاقلُ الرشيدُ من يميّز الأحسنَ فيأخذ به، والأقبحَ فيدعه؛ فاطلب الحقَّ حيثما كان، واتّبع أحسنَ ما تسمع؛ فخذ الحكمةَ ولو من غيرِ أهلها؛ فالحكمةُ ضالّةُ المؤمن؛ فاستمع للنصحِ والعلمِ والحقِّ بقلبٍ منفتح، ثم اتّبع أرشده وأصوبه؛ فمن فعل ذلك فقد هداه الله وكان من أولي الألباب؛ فاجعل عقلك ميزانًا تزن به الأقوال، فتأخذ أحسنها وتدع أدناها؛ فبتحرّي الأحسنِ واتّباعِه تكون من المهتدين العقلاء."}},{"n":19,"reflection":{"text":"«أفمن حق عليه كلمة العذاب أفأنت تنقذ من في النار» — أفمن وجب عليه العذابُ لكفره وإصراره تقدر على هدايته؟ أفأنت يا محمدُ تنقذ من كتب الله عليه النار؟ ففي هذا تسليةُ النبيِّ وبيانُ أنّ الهدايةَ بيدِ الله؛ فاعلم أنّ الهدايةَ بيدِ الله، فابذل الدعوةَ ولا تحزن على من لم يهتدِ، فليس عليك هداهم بل البلاغ، فوكِّل أمرَ الهدايةِ إلى الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الهدايةَ بيدِ الله، وبذلُ الدعوةِ دون حزنٍ على المعرض."},"action":{"text":"تأمّل تسليةَ الله لنبيّه: أفمن وجبت عليه كلمةُ العذابِ وحقّ عليه لكفره وإصراره على الضلال، تقدر على هدايته وإنقاذه؟ أفأنت يا محمدُ تنقذ من كتب الله عليه أن يكون في النار؟ لست بقادرٍ على ذلك، إنما عليك البلاغ «أفمن حق عليه كلمة العذاب أفأنت تنقذ من في النار»؛ ففي هذا تسليةٌ للنبيِّ ﷺ على إعراضِ المكذّبين، وبيانٌ أنّ الهدايةَ بيدِ الله وحده؛ فاعلم أنّ الهدايةَ — هدايةَ التوفيقِ والقبول — بيدِ الله، ليست بيدك ولا بيدِ أحدٍ من الخلق؛ إنك لا تهدي من أحببت ولكنّ الله يهدي من يشاء؛ فابذل الدعوةَ والنصحَ والبيانَ لمن حولك؛ ثم لا تحزن ولا تأسف على من لم يهتدِ بعد بلوغِ الحجّة؛ فليس عليك هداهم، بل عليك البلاغُ والدعوة، وعلى الله الهداية؛ فلا تذهب نفسك عليهم حسرات؛ فما أنت عليهم بمسيطر؛ فأدِّ ما عليك من الدعوةِ والنصح، ووكِّل أمرَ الهدايةِ والقبولِ إلى الله؛ فمن كتب الله له الهدايةَ اهتدى، ومن حقّ عليه العذابُ بإصراره لم ينفع فيه نصحٌ ولا دعوة؛ فاجتهد في الدعوة، وأحسن الظنَّ بالله، ولا تحمل نفسك ما لا تطيق؛ فالهدايةُ بيدِ الله، والبلاغُ عليك."}},{"n":20,"reflection":{"text":"«لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنية تجري من تحتها الأنهار وعد الله لا يخلف الله الميعاد» — لكن الذين اتّقوا ربّهم لهم غرفٌ عاليةٌ فوقها غرفٌ مبنيّةٌ تجري من تحتها الأنهار، وعدًا من الله لا يخلفه؛ ففي هذا بشارةُ المتّقين بالمنازلِ العاليةِ في الجنّة؛ فاتّق الله لتنال الغرفَ العاليةَ في الجنّة، فوعدُ الله حقٌّ لا يُخلَف، فاعمل عملَ المتّقين لتفوز بمنازلهم، فالجنّةُ درجاتٌ تُنال بالتقوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى رجاءَ المنازلِ العاليةِ في الجنّة، والثقةُ بوعدِ الله."},"action":{"text":"تأمّل بشارةَ الله للمتّقين: لكن الذين اتّقوا ربّهم — امتثالًا لأمره واجتنابًا لنهيه — لهم في الجنّةِ غرفٌ عاليةٌ رفيعة، من فوقها غرفٌ أخرى مبنيّةٌ محكمة، تجري من تحتها الأنهار، وعدًا من الله حقًّا، لا يخلف الله وعده «لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنية تجري من تحتها الأنهار وعد الله لا يخلف الله الميعاد»؛ ففي هذا بشارةُ المتّقين بالمنازلِ العاليةِ والغرفِ الرفيعةِ في الجنّة؛ فاتّق الله لتنال هذه الغرفَ العاليةَ في جنّاتِ النعيم؛ فالجنّةُ درجاتٌ ومنازلُ متفاوتة، أعلاها للمتّقين المحسنين؛ فاعمل عملَ المتّقين لتفوز بمنازلهم العالية؛ واعلم أنّ وعدَ الله بالجنّةِ للمتّقين حقٌّ لا يُخلَف؛ فإنّ الله لا يخلف الميعاد؛ فثق بوعدِ الله، واعمل لنيلِ موعوده؛ فارفع همّتك إلى المنازلِ العالية في الجنّة؛ واعمل لها بالتقوى والإحسانِ والمسابقةِ في الخيرات؛ فمن علت همّته إلى الفردوسِ الأعلى عمل له؛ فاسأل الله الفردوسَ الأعلى؛ واعمل عملَ أهله من التقوى والطاعةِ والإحسان؛ فبالتقوى تُنال الغرفُ العاليةُ، وينجز الله وعده للمتّقين."}}]},{"title":"آيةُ الماءِ والزرع، وشرحُ الصدرِ وأحسنُ الحديث، وعاقبةُ المكذّبين، ومثلُ التوحيدِ والموت","range":[21,31],"theme":"آيةُ إنزالِ الماءِ وإخراجِ الزرعِ ثم يبسِه عبرةً بفناءِ الدنيا، والموازنةُ بين منشرحِ الصدرِ وقاسي القلب، ووصفُ القرآنِ بأنه أحسنُ الحديثِ تقشعرّ منه الجلودُ ثم تلين، وحالُ من يتّقي العذابَ بوجهه، وعاقبةُ المكذّبين بالخزيِ في الدنيا والعذابِ الأكبر، وضربُ الأمثالِ في القرآنِ العربيِّ المستقيم، ومثلُ المشركِ المتحيّرِ والموحّدِ المطمئن، والتذكيرُ بالموتِ وخصومةِ يومِ القيامة","verses":[{"n":21,"reflection":{"text":"«ألم تر أن الله أنزل من السماء ماء فسلكه ينابيع في الأرض ثم يخرج به زرعا مختلفا ألوانه ثم يهيج فتراه مصفرا ثم يجعله حطاما إن في ذلك لذكرى لأولي الألباب» — ألم تر أنّ الله أنزل المطرَ فأجراه عيونًا في الأرض، ثم أخرج به زرعًا مختلفَ الألوان، ثم ييبس فتراه أصفر، ثم يجعله فتاتًا، إنّ في ذلك لعبرةً لأصحابِ العقول؟ ففي هذا آيةُ الماءِ والزرعِ على القدرةِ والبعث، وعبرةُ فناءِ الدنيا؛ فاعتبر بحالِ الزرعِ الذي يخضرّ ثم ييبس ويصير حطامًا، فكذلك الدنيا وأهلها، فلا تغترّ بزينةِ الدنيا الفانية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بفناءِ الدنيا كالزرعِ، وعدمُ الاغترارِ بزينتها."},"action":{"text":"تأمّل آيةَ الله في الماءِ والزرع: ألم تر أنّ الله أنزل من السماءِ ماءً — وهو المطر — فسلكه وأجراه ينابيعَ وعيونًا في الأرض، ثم يخرج به زرعًا مختلفًا ألوانه وأنواعه، ثم ييبس ويجفّ فتراه مصفرًّا بعد خضرته، ثم يجعله حطامًا متكسّرًا فتاتًا، إنّ في ذلك لذكرى وعبرةً لأولي الألباب «ألم تر أن الله أنزل من السماء ماء... ثم يهيج فتراه مصفرا ثم يجعله حطاما إن في ذلك لذكرى لأولي الألباب»؛ ففي هذا آيةٌ على قدرةِ الله وإحيائه الأرضَ ثم إماتتها، وهي دليلٌ على البعث؛ وفيها عبرةٌ بفناءِ الدنيا وزينتها؛ فاعتبر بحالِ الزرعِ الذي يخرج نضرًا أخضرَ ثم ييبس ويصفرّ ثم يصير حطامًا؛ فكذلك الدنيا وأهلها: شبابٌ ونضارةٌ ثم هرمٌ وذبولٌ ثم فناء؛ واعلم أنّ الدنيا كماءٍ أنزلناه من السماءِ فاختلط به نباتُ الأرض... حتى إذا أخذت الأرضُ زخرفها وازّيّنت وظنّ أهلها أنهم قادرون عليها أتاها أمرنا ليلًا أو نهارًا فجعلناها حصيدًا؛ فلا تغترّ بزينةِ الدنيا الفانيةِ الزائلة؛ ولا تركن إليها؛ بل اعمل للباقيةِ لا للفانية؛ فمن اعتبر بفناءِ الدنيا زهد فيها وعمل لآخرته؛ فاجعل من مشهدِ الزرعِ الذي يخضرّ ثم ييبس عبرةً تزهّدك في الدنيا وتحملك على العملِ للآخرة."}},{"n":22,"reflection":{"text":"«أفمن شرح الله صدره للإسلام فهو على نور من ربه فويل للقاسية قلوبهم من ذكر الله أولئك في ضلال مبين» — أفمن وسّع الله صدره للإسلامِ فهو على نورٍ وبصيرةٍ من ربه كمن قسا قلبه؟ فويلٌ للقاسيةِ قلوبهم من ذكرِ الله، أولئك في ضلالٍ بيّن؛ ففي هذا الموازنةُ بين منشرحِ الصدرِ وقاسي القلب؛ فاطلب من الله أن يشرح صدرك للإسلام، واحذر قسوةَ القلبِ عن ذكرِ الله، فليّنِ القلبِ بالذكرِ سبيلُ النور، وقسوتُه سبيلُ الضلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ شرحِ الصدرِ للإسلام، والحذرُ من قسوةِ القلب."},"action":{"text":"تأمّل موازنةَ الله بين شتّانِ القلوب: أفمن شرح الله صدره ووسّعه لقبولِ الإسلامِ والإيمان، فهو على نورٍ وبصيرةٍ وهدًى من ربه، كمن قسا قلبه وأعرض؟ لا يستويان؛ فويلٌ وعذابٌ للقاسيةِ قلوبهم عن ذكرِ الله، الذين لا يلين قلبهم لذكره ولا ينتفعون بمواعظه، أولئك في ضلالٍ واضحٍ بيّن «أفمن شرح الله صدره للإسلام فهو على نور من ربه فويل للقاسية قلوبهم من ذكر الله أولئك في ضلال مبين»؛ ففي هذا الموازنةُ بين منشرحِ الصدرِ المنوَّرِ بالإيمان، وقاسي القلبِ المعرضِ عن الذكر؛ فاطلب من الله أن يشرح صدرك للإسلامِ والإيمانِ والطاعة؛ فمن يرد الله أن يهديه يشرح صدره للإسلام؛ واحذر قسوةَ القلبِ عن ذكرِ الله وموعظته؛ فقسوةُ القلبِ من أعظمِ العقوبات؛ فمن علاماتها: الإعراضُ عن الذكر، وعدمُ التأثّرِ بالموعظة، والغفلةُ عن الله؛ فليّنِ القلبِ بالذكرِ والقرآنِ والموعظةِ سبيلُ النورِ والهداية، وقسوتُه عنها سبيلُ الضلال؛ فعالج قسوةَ قلبك بكثرةِ ذكرِ الله وتلاوةِ القرآنِ وتذكّرِ الموتِ والآخرة؛ فاسأل الله قلبًا ليّنًا خاشعًا منشرحًا؛ ونعوذ بالله من قلبٍ لا يخشع؛ فالقلبُ المنشرحُ بالنورِ سعيد، والقاسي في ضلالٍ مبين."}},{"n":23,"reflection":{"text":"«الله نزل أحسن الحديث كتابا متشابها مثاني تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم إلى ذكر الله ذلك هدى الله يهدي به من يشاء ومن يضلل الله فما له من هاد» — الله نزّل أحسنَ الكلامِ (القرآن) كتابًا يشبه بعضه بعضًا في الحسنِ والصدق، تُثنّى فيه المعاني، تقشعرّ منه جلودُ الخاشين ثم تلين جلودهم وقلوبهم إلى ذكرِ الله، ذلك هدى الله يهدي به من يشاء؛ ففي هذا وصفُ أثرِ القرآنِ في قلوبِ الخاشين؛ فاجعل للقرآنِ أثرًا في قلبك، فتخشع لسماعه وتلين له، فأثرُ القرآنِ في القلبِ علامةُ الإيمانِ والخشية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأثّرُ بالقرآنِ خشوعًا ولينًا، فذلك علامةُ الخشية."},"action":{"text":"تأمّل وصفَ الله لكتابه وأثرِه: الله نزّل أحسنَ الحديثِ والكلامِ — وهو القرآن — كتابًا متشابهًا يشبه بعضه بعضًا في الحسنِ والصدقِ والإحكام، مثانيَ تُثنّى وتُكرّر فيه المعاني والقصصُ والأحكامُ لترسخ، تقشعرّ منه جلودُ الذين يخشون ربهم عند سماعِ آياتِ الوعيد، ثم تلين جلودهم وقلوبهم إلى ذكرِ الله عند سماعِ آياتِ الرحمة، ذلك القرآنُ هدى الله يهدي به من يشاء، ومن يضلله الله فما له من هادٍ «الله نزل أحسن الحديث كتابا متشابها مثاني تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم إلى ذكر الله...»؛ ففي هذا وصفُ أثرِ القرآنِ العظيمِ في قلوبِ الخاشين لله؛ فالمؤمنُ الخاشعُ يتأثّر بالقرآنِ خوفًا ورجاءً، فتقشعرّ جلوده عند الوعيد، وتلين قلوبه عند الرحمة؛ فاجعل للقرآنِ أثرًا في قلبك؛ فتخشع لسماعه، وتقشعرّ لوعيده، وتلين لرحمته؛ فأثرُ القرآنِ في القلبِ علامةُ الإيمانِ والخشيةِ والحياة؛ إنما المؤمنون الذين إذا ذُكِر الله وجلت قلوبهم، وإذا تُلِيت عليهم آياته زادتهم إيمانًا؛ فاقرأ القرآنَ بتدبّرٍ وحضورِ قلب، واستشعر عظمةَ المتكلّمِ به؛ فإن لم تجد لقلبك أثرًا فاتّهم قلبك بالقسوة، وعالجه؛ فالقلبُ الحيُّ يتأثّر بأحسنِ الحديث؛ فاجعل قلبك يخشع ويلين لكتابِ ربك؛ فبالتأثّرِ بالقرآنِ تحيا القلوبُ وتهتدي."}},{"n":24,"reflection":{"text":"«أفمن يتقي بوجهه سوء العذاب يوم القيامة وقيل للظالمين ذوقوا ما كنتم تكسبون» — أفمن يتّقي شدّةَ العذابِ بوجهه (لأنه مغلولٌ لا يقيه بيديه) كمن هو آمنٌ في الجنّة؟ وقيل للظالمين: ذوقوا جزاءَ ما كسبتم؛ ففي هذا الموازنةُ بين المعذَّبِ والآمن؛ فاحذر أن تكون من الظالمين الذين يُقال لهم ذوقوا، فاعمل لتكون من الآمنين، فالظالمُ يذوق جزاءَ عمله، فاجتنب الظلمَ والمعاصي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ الظالمين، والعملُ للأمنِ يومَ القيامة."},"action":{"text":"تأمّل الموازنةَ بين حالِ المعذَّبِ والآمن: أفمن يتّقي ويدفع شدّةَ العذابِ يومَ القيامةِ بوجهه — لأنه يُلقى في النارِ مغلولةً يداه لا يستطيع أن يقيَ نفسه بهما، فيتّقي النارَ بوجهه الذي هو أشرفُ أعضائه — كمن هو آمنٌ ناعمٌ في الجنّة؟ لا يستويان؛ وقيل للظالمين توبيخًا: ذوقوا جزاءَ ما كنتم تكسبون من الكفرِ والمعاصي «أفمن يتقي بوجهه سوء العذاب يوم القيامة وقيل للظالمين ذوقوا ما كنتم تكسبون»؛ ففي هذا الموازنةُ بين المعذَّبِ في النارِ والآمنِ في الجنّة؛ فاحذر أن تكون من الظالمين الذين يُقال لهم يومَ القيامة: ذوقوا ما كنتم تكسبون؛ فاعمل لتكون من الآمنين يومَ الفزعِ الأكبر؛ فالظالمُ لنفسه بالكفرِ والمعاصي يذوق جزاءَ عمله؛ والجزاءُ من جنسِ العمل؛ فاجتنب الظلمَ بأنواعه: ظلمَ النفسِ بالشركِ والمعاصي، وظلمَ الغيرِ بالتعدّي على حقوقهم؛ فالظلمُ ظلماتٌ يومَ القيامة؛ فمن اتّقى الله وعمل صالحًا أمِن يومَ القيامة، ومن ظلم وعصى عُذّب؛ فاعمل عملَ الآمنين من الإيمانِ والتقوى والعملِ الصالح؛ واجتنب عملَ الظالمين من الكفرِ والظلمِ والمعاصي؛ فبالتقوى تنجو من سوءِ العذاب، وتفوز بالأمنِ يومَ القيامة."}},{"n":25,"reflection":{"text":"«كذب الذين من قبلهم فأتاهم العذاب من حيث لا يشعرون» — كذّب المكذّبون قبل هؤلاء فأتاهم العذابُ بغتةً من حيث لا يتوقّعون؛ ففي هذا التخويفُ من مباغتةِ العذاب؛ فاحذر أن يأتيك العذابُ أو الموتُ بغتةً وأنت غافل، فاستعدّ دائمًا، فالعذابُ قد يأتي من حيث لا يُحتسَب، فكن على حذرٍ واستعدادٍ بالطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ الدائمُ بالطاعة، والحذرُ من مباغتةِ العذاب."},"action":{"text":"اعلم أنّ الأممَ المكذّبةَ قبل مشركي قريشٍ كذّبت رسلها، فأتاهم عذابُ الله بغتةً من حيث لا يشعرون ولا يتوقّعون، وهم آمنون غافلون «كذب الذين من قبلهم فأتاهم العذاب من حيث لا يشعرون»؛ ففي هذا التخويفُ من مباغتةِ العذابِ ومجيئِه على غفلة؛ فاحذر أن يأتيك عذابُ الله أو الموتُ بغتةً وأنت غافلٌ مصرٌّ على المعصية؛ أفأمن أهلُ القرى أن يأتيهم بأسنا بياتًا وهم نائمون؟ أوأمن أهلُ القرى أن يأتيهم بأسنا ضحًى وهم يلعبون؟ فاستعدّ دائمًا للقاءِ الله؛ فالعذابُ والموتُ قد يأتيان من حيث لا تحتسب، وفي وقتٍ لا تتوقّع؛ فكن على حذرٍ واستعدادٍ بالطاعةِ والتوبةِ في كلِّ حين؛ ولا تأمن مكرَ الله؛ فلا يأمن مكرَ الله إلا القومُ الخاسرون؛ فاجعل نفسك مستعدًّا للرحيلِ في كلِّ لحظة؛ فبادر بالتوبةِ والطاعةِ قبل أن يفاجئك الموتُ أو العذاب؛ فالكيّسُ من دان نفسه وعمل لما بعد الموت؛ فلا تسوّف بالتوبةِ والعمل؛ فاجعل الاستعدادَ للقاءِ الله دأبك؛ فمن استعدّ بالطاعةِ لم يضرّه مباغتةُ الموتِ أو العذاب."}},{"n":26,"reflection":{"text":"«فأذاقهم الله الخزي في الحياة الدنيا ولعذاب الآخرة أكبر لو كانوا يعلمون» — فأذاقهم الله الذلَّ والفضيحةَ في الدنيا، ولعذابُ الآخرةِ أعظمُ لو كانوا يعلمون؛ ففي هذا بيانُ عقوبةِ المكذّبين في الدارين؛ فاعلم أنّ المعصيةَ تجرّ الخزيَ في الدنيا والعذابَ الأكبرَ في الآخرة، فاجتنب أسبابَ الخزيِ والعذاب، والزم الطاعةَ لتنال العزّةَ في الدارين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ أسبابِ الخزيِ والعذاب، ولزومُ الطاعةِ لعزّةِ الدارين."},"action":{"text":"اعلم أنّ الله عاقب المكذّبين في الدنيا والآخرة: فأذاقهم الخزيَ والذلَّ والفضيحةَ في الحياةِ الدنيا بالهلاكِ والعذابِ العاجل، ولعذابُ الآخرةِ أكبرُ وأعظمُ وأدومُ لو كانوا يعلمون «فأذاقهم الله الخزي في الحياة الدنيا ولعذاب الآخرة أكبر لو كانوا يعلمون»؛ ففي هذا بيانُ أنّ عقوبةَ المكذّبين والعاصين في الدارين: خزيٌ في الدنيا وعذابٌ أكبرُ في الآخرة؛ فاعلم أنّ المعصيةَ والتكذيبَ يجرّان الخزيَ والذلَّ في الدنيا، والعذابَ الأكبرَ الدائمَ في الآخرة؛ فاجتنب أسبابَ الخزيِ والعذابِ من الكفرِ والمعاصي والظلم؛ والزم طاعةَ الله وتقواه؛ فبالطاعةِ تُنال العزّةُ في الدنيا والنجاةُ في الآخرة، وبالمعصيةِ يُنال الخزيُ في الدنيا والعذابُ في الآخرة؛ فمن أراد العزّةَ فليطع الله؛ فإنّ العزّةَ لله ولرسولِه وللمؤمنين؛ فالطاعةُ عزٌّ وإن ظنّها الناسُ ذلًّا، والمعصيةُ ذلٌّ وإن ظنّها الناسُ عزًّا؛ فاطلب العزّةَ في الدارين بطاعةِ الله؛ واجتنب الخزيَ والعذابَ باجتنابِ معصيته؛ فمن أطاع الله أعزّه وأكرمه، ومن عصاه أخزاه وأذلّه؛ فالزم الطاعةَ لتنال عزّةَ الدنيا ونعيمَ الآخرة."}},{"n":27,"reflection":{"text":"«ولقد ضربنا للناس في هذا القرآن من كل مثل لعلهم يتذكرون» — ولقد ضربنا للناسِ في هذا القرآنِ من كلِّ مثلٍ يحتاجونه لعلّهم يتّعظون؛ ففي هذا بيانُ حكمةِ الأمثالِ في القرآن؛ فتدبّر أمثالَ القرآنِ واتّعظ بها، فالأمثالُ تقرّب المعانيَ وتعين على الفهمِ والاتّعاظ، فتأمّل في أمثالِ القرآنِ لتزداد فهمًا وعبرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ أمثالِ القرآنِ والاتّعاظُ بها."},"action":{"text":"اعلم أنّ الله ضرب للناسِ في هذا القرآنِ من كلِّ مثلٍ يحتاجونه لبيانِ الحقِّ وتقريبِ المعاني، لعلّهم يتذكّرون ويتّعظون وينتفعون «ولقد ضربنا للناس في هذا القرآن من كل مثل لعلهم يتذكرون»؛ ففي هذا بيانُ حكمةِ الأمثالِ في القرآن، وأنها من رحمةِ الله بعباده لتقريبِ الحقِّ إليهم؛ فتدبّر أمثالَ القرآنِ واتّعظ بها؛ فالأمثالُ تقرّب المعانيَ العقليةَ بصورةٍ محسوسة، وتعين على الفهمِ والاتّعاظِ والاعتبار؛ وتلك الأمثالُ نضربها للناسِ وما يعقلها إلا العالمون؛ فتأمّل في أمثالِ القرآنِ التي ضربها الله: مثلِ المنافقين، ومثلِ الكافرين، ومثلِ الدنيا، ومثلِ الحقِّ والباطل، ومثلِ كلمةِ التوحيد؛ فكلُّ مثلٍ فيه عبرةٌ ودرسٌ وحكمة؛ فمن تدبّر أمثالَ القرآنِ ازداد فهمًا وعلمًا وعبرة؛ فلا تمرّ على أمثالِ القرآنِ مرورًا عابرًا؛ بل قف عندها، وتأمّل معانيها، واستخلص عبرها؛ فالأمثالُ من أبلغِ ما يرسّخ المعنى في القلب؛ فاجعل تدبّرَ أمثالِ القرآنِ من عنايتك؛ فبها تفهم الحقَّ، وتتّعظ، وتعتبر؛ فالله ما ضرب الأمثالَ إلا لينتفع بها المتذكّرون."}},{"n":28,"reflection":{"text":"«قرآنا عربيا غير ذي عوج لعلهم يتقون» — أنزلناه قرآنًا عربيًّا واضحًا لا اعوجاجَ فيه ولا لبس، لعلّهم يتّقون؛ ففي هذا بيانُ وضوحِ القرآنِ واستقامتِه؛ فاعلم أنّ القرآنَ واضحٌ مستقيمٌ لا عوجَ فيه، فاتّبعه واعمل به، فمن اتّبع القرآنَ المستقيمَ اتّقى الله واهتدى، فاجعل القرآنَ إمامك المستقيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ القرآنِ المستقيمِ الواضح، فهو سبيلُ التقوى."},"action":{"text":"اعلم أنّ الله أنزل القرآنَ عربيًّا بيّنًا واضحًا، غيرَ ذي عوجٍ ولا اعوجاجٍ ولا لبسٍ ولا تناقض، مستقيمًا في ألفاظه ومعانيه، لعلّ الناسَ يتّقون الله باتّباعه «قرآنا عربيا غير ذي عوج لعلهم يتقون»؛ ففي هذا بيانُ وضوحِ القرآنِ واستقامتِه وسلامتِه من كلِّ عيب؛ فالقرآنُ عربيٌّ مبينٌ واضحُ الدلالة، مستقيمُ المعاني، لا عوجَ فيه ولا انحراف؛ فاعلم أنّ القرآنَ مستقيمٌ لا اعوجاجَ فيه؛ فاتّبعه، واعمل به، واهتدِ بهديه؛ فمن اتّبع القرآنَ المستقيمَ اتّقى الله واهتدى إلى الصراطِ المستقيم؛ فالقرآنُ سبيلُ التقوى؛ إنّ هذا القرآنَ يهدي للتي هي أقوم؛ فاجعل القرآنَ إمامك ودليلك المستقيم؛ ولا تلتمس الهدى في غيره؛ فمن ابتغى الهدى في غيرِ القرآنِ أضلّه الله؛ فالقرآنُ حبلُ الله المتين، وصراطُه المستقيم؛ فتمسّك به تلاوةً وتدبّرًا وعملًا وتحكيمًا؛ فبالقرآنِ المستقيمِ الواضحِ تُنال التقوى والهداية؛ فاتّبعه، فإنه لا عوجَ فيه، ولا يضلّ من اتّبعه."}},{"n":29,"reflection":{"text":"«ضرب الله مثلا رجلا فيه شركاء متشاكسون ورجلا سلما لرجل هل يستويان مثلا الحمد لله بل أكثرهم لا يعلمون» — ضرب الله مثلًا للمشركِ والموحّد: عبدًا يملكه شركاءُ متنازعون متعاسرون، وعبدًا خالصًا لسيّدٍ واحد، هل يستويان؟ الحمد لله، بل أكثرهم لا يعلمون؛ ففي هذا مثلٌ لراحةِ الموحّدِ وشقاءِ المشرك؛ فكن موحّدًا خالصًا لله وحده لتنعم براحةِ التوحيد، فالمشركُ متحيّرٌ بين آلهةٍ، والموحّدُ مطمئنٌّ لربٍّ واحد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبوديةِ لله وحده، فراحةُ التوحيدِ وطمأنينتُه."},"action":{"text":"تأمّل المثلَ الذي ضربه الله للمشركِ والموحّد: عبدٌ مملوكٌ يملكه شركاءُ كثيرون متنازعون متعاسرون، كلٌّ منهم يأمره بأمرٍ ويجذبه إلى جهة، فهو متحيّرٌ قلقٌ لا يدري أيّهم يرضي؛ وعبدٌ آخرُ خالصٌ سالمٌ لسيّدٍ واحدٍ يعرف مراده ويطمئنّ إليه؛ هل يستويان مثلًا؟ لا يستويان؛ الحمد لله على وضوحِ الحجّة، بل أكثرُ الناسِ لا يعلمون «ضرب الله مثلا رجلا فيه شركاء متشاكسون ورجلا سلما لرجل هل يستويان مثلا الحمد لله بل أكثرهم لا يعلمون»؛ ففي هذا مثلٌ عظيمٌ لراحةِ الموحّدِ وطمأنينته، وشقاءِ المشركِ وحيرته؛ فالمشركُ كالعبدِ المملوكِ لشركاءَ متنازعين: قلبه موزّعٌ بين معبوداتٍ شتّى، متحيّرٌ قلقٌ لا يستقرّ؛ والموحّدُ كالعبدِ الخالصِ لسيّدٍ واحد: قلبه مطمئنٌّ لربٍّ واحدٍ يعبده ويتوكّل عليه ويرجوه؛ فكن موحّدًا خالصًا لله وحده؛ فبالتوحيدِ تنعم بالراحةِ والطمأنينةِ وجمعِ القلب؛ فالتوحيدُ يجمع القلبَ على معبودٍ واحد، والشركُ يمزّقه بين معبوداتٍ شتّى؛ ألا بذكرِ الله تطمئنّ القلوب؛ فأخلص عبوديتك لله وحده؛ ولا توزّع قلبك بين الله وغيره؛ فمن أخلص لله استراح واطمأنّ، ومن أشرك تحيّر وشقي؛ فالحمد لله على نعمةِ التوحيدِ التي بها راحةُ القلبِ وطمأنينته؛ فاعبد ربًّا واحدًا، تنعم بجمعِ القلبِ وسكينته."}},{"n":30,"reflection":{"text":"«إنك ميت وإنهم ميتون» — إنك يا محمدُ ميّتٌ لا محالة، وإنهم ميّتون كذلك، فالموتُ يعمّ الجميع؛ ففي هذا تذكيرٌ بالموتِ الذي لا مفرَّ منه؛ فتذكّر الموتَ واستعدّ له، فالموتُ حقٌّ على كلِّ نفس، حتى الأنبياء، فاعمل لما بعد الموت، ولا تغترّ بالحياةِ الفانية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ الموتِ الذي يعمُّ الجميع، والاستعدادُ له."},"action":{"text":"تأمّل تذكيرَ الله بالموت: إنك يا محمدُ ميّتٌ لا محالة، وإنهم ميّتون كذلك، فالموتُ حقٌّ يعمّ الجميع، لا ينجو منه أحدٌ حتى أشرفُ الخلق «إنك ميت وإنهم ميتون»؛ ففي هذا تذكيرٌ بالموتِ الذي لا مفرَّ منه ولا مهرب؛ فإذا كان النبيُّ ﷺ — سيّدُ الخلقِ وأكرمهم على الله — سيموت، فغيره أولى؛ كلُّ نفسٍ ذائقةُ الموت؛ فتذكّر الموتَ الذي هو نهايةُ كلِّ حي؛ واستعدّ له بالإيمانِ والعملِ الصالحِ والتوبة؛ فالموتُ حقٌّ على كلِّ نفس، حتى الأنبياءِ والصالحين؛ فأكثر من ذكرِ الموتِ هادمِ اللذّات؛ فمن أكثر ذكرَ الموتِ استعدّ له، وقصّر أمله، وأحسن عمله؛ فلا تغترّ بالحياةِ الدنيا الفانية؛ ولا تنسَ أنّ الموتَ يأتيك لا محالة؛ فاعمل لما بعد الموتِ من الحياةِ الباقية؛ فالكيّسُ من دان نفسه وعمل لما بعد الموت، والعاجزُ من أتبع نفسه هواها وتمنّى على الله؛ فاجعل ذكرَ الموتِ حافزًا لك على العملِ والاستعداد؛ فمن علم أنه ميّتٌ عمل لما بعد الموت؛ فتزوّد لآخرتك، وأحسن عملك، قبل أن يأتيك الموتُ الذي لا مفرَّ منه."}},{"n":31,"reflection":{"text":"«ثم إنكم يوم القيامة عند ربكم تختصمون» — ثم إنكم يومَ القيامةِ عند ربّكم تختصمون، يحاجّ بعضكم بعضًا، ويُفصَل بينكم بالحق؛ ففي هذا بيانُ الخصومةِ والحسابِ يومَ القيامة؛ فاحذر مظالمَ العبادِ فإنها تُطلَب يومَ القيامة، وأدِّ الحقوقَ لأهلها في الدنيا، فمن ظلم أحدًا اقتُصّ منه يومَ الخصومةِ الكبرى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ الحقوقِ في الدنيا، والحذرُ من خصومةِ يومِ القيامة."},"action":{"text":"تأمّل بيانَ الله للخصومةِ يومَ القيامة: ثم إنكم يومَ القيامةِ عند ربّكم تختصمون، فيحاجّ بعضكم بعضًا، ويطلب المظلومُ حقّه من الظالم، ويُفصَل بينكم بالحقِّ والعدل «ثم إنكم يوم القيامة عند ربكم تختصمون»؛ ففي هذا بيانُ أنّ الخصوماتِ والمظالمَ تُرفَع إلى الله يومَ القيامة، فيقتصّ للمظلومِ من الظالم؛ فاحذر مظالمَ العباد؛ فإنها لا تُترَك، بل تُطلَب يومَ القيامةِ حين لا دينارَ ولا درهم، إلا الحسناتُ والسيّئات؛ فمن كانت عنده مظلمةٌ لأخيه فليتحلّلها منه اليوم قبل ألا يكون دينارٌ ولا درهم؛ فأدِّ الحقوقَ لأهلها في الدنيا: حقوقَ الله، وحقوقَ العباد؛ وردّ المظالمَ إلى أصحابها، واستحلّهم؛ فمن ظلم أحدًا في مالٍ أو عرضٍ أو دمٍ اقتُصّ منه يومَ الخصومةِ الكبرى؛ أتدرون من المفلس؟ المفلسُ من يأتي بحسناتٍ كثيرةٍ وقد ظلم هذا وشتم هذا، فيُؤخَذ من حسناته لهم؛ فتحلّل من مظالمِ الناسِ اليوم؛ وأدِّ الحقوقَ، واجتنب الظلم؛ فبذلك تنجو من خصومةِ يومِ القيامة؛ فاحذر أن تلقى الله وفي صحيفتك مظالمُ للعباد؛ فبادر بردّها والتحلّلِ منها؛ فالسلامةُ في أداءِ الحقوقِ واجتنابِ المظالم."}}]},{"title":"أظلمُ الناسِ ومن جاء بالصدق، وجزاءُ المتّقين المحسنين ومغفرةُ سيّئاتهم","range":[32,35],"theme":"أنه لا أظلمَ ممّن كذب على الله وكذّب بالصدقِ وأنّ مثواه جهنم، وأنّ من جاء بالصدقِ وصدّق به هم المتّقون لهم ما يشاؤون عند ربهم جزاءَ إحسانهم، وأنّ الله يكفّر عنهم أسوأَ أعمالهم ويجزيهم بأحسنِ ما عملوا","verses":[{"n":32,"reflection":{"text":"«فمن أظلم ممن كذب على الله وكذب بالصدق إذ جاءه أليس في جهنم مثوى للكافرين» — لا أحد أظلمُ ممّن كذب على الله بنسبةِ الشريكِ والولدِ إليه، وكذّب بالصدقِ (القرآنِ والرسول) حين جاءه، أليس في جهنمَ مأوًى للكافرين؟ ففي هذا أنّ الكذبَ على الله وتكذيبَ الحقِّ أعظمُ الظلم؛ فاحذر الكذبَ على الله وتكذيبَ الحقّ، فهما أعظمُ الظلمِ وسببُ النار، فاصدق مع الله وصدّق بالحقِّ لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكذبِ على الله وتكذيبِ الحقّ، فهما أعظمُ الظلم."},"action":{"text":"اعلم أنّ الله بيّن أنه لا أحد أظلمُ وأشدُّ جرمًا ممّن جمع بين أمرين: الكذبِ على الله بنسبةِ الشريكِ والولدِ والصاحبةِ إليه وتحليلِ ما حرّم وتحريمِ ما أحلّ، وتكذيبِ الصدقِ — وهو القرآنُ والرسولُ ﷺ — حين جاءه؛ أليس في جهنمَ مأوًى ومستقرٌّ للكافرين؟ «فمن أظلم ممن كذب على الله وكذب بالصدق إذ جاءه أليس في جهنم مثوى للكافرين»؛ ففي هذا أنّ الكذبَ على الله وتكذيبَ الحقِّ من أعظمِ الظلمِ وأكبرِ الجرم؛ فاحذر الكذبَ على الله بجميعِ صوره: نسبةِ ما لا يليق به، والقولِ عليه بلا علم، وتحليلِ الحرامِ وتحريمِ الحلالِ بلا دليل؛ واحذر تكذيبَ الحقِّ إذا جاءك واضحًا؛ فهما أعظمُ الظلمِ وسببُ دخولِ النار؛ فاصدق مع الله في قولك وعملك؛ وصدّق بالحقِّ الذي جاء به الرسولُ ﷺ؛ فمن صدق مع الله وصدّق بالحقِّ نجا، ومن كذب على الله وكذّب بالحقِّ هلك؛ فالزم الصدقَ، واقبل الحقَّ، واحذر أن تقول على الله بلا علم؛ فبذلك تنجو من الظلمِ الأعظمِ ومن مثوى الكافرين."}},{"n":33,"reflection":{"text":"«والذي جاء بالصدق وصدق به أولئك هم المتقون» — والذي جاء بالصدقِ (الرسولُ) والذين صدّقوا به (أتباعه)، أولئك هم المتّقون حقًّا؛ ففي هذا مدحُ الصادقين المصدّقين بالحقّ؛ فكن من المصدّقين بالحقِّ العاملين به لتكون من المتّقين، فالتقوى في تصديقِ الحقِّ والعملِ به، فصدّق بالحقِّ واعمل به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بالحقِّ والعملُ به، فذلك سبيلُ التقوى."},"action":{"text":"تأمّل مدحَ الله للصادقين المصدّقين: والذي جاء بالصدقِ من عند الله — وهو الرسولُ محمدٌ ﷺ الذي جاء بالقرآنِ والتوحيد — والذين صدّقوا به من أتباعه وعملوا بما جاء به، أولئك هم المتّقون حقًّا الذين اتّقوا الشركَ والمعاصي «والذي جاء بالصدق وصدق به أولئك هم المتقون»؛ ففي هذا مدحُ من جاء بالحقِّ ومن صدّق به وعمل بمقتضاه؛ فكن من المصدّقين بالحقِّ العاملين به لتكون من المتّقين؛ فالتقوى الحقيقيةُ في تصديقِ الحقِّ الذي جاء به الرسولُ والعملِ به؛ فليست التقوى مجرّدَ دعوًى، بل تصديقٌ بالقلبِ وعملٌ بالجوارح؛ فصدّق بالقرآنِ والسنّةِ تصديقًا جازمًا؛ واعمل بما فيهما من الأوامرِ والنواهي؛ فمن صدّق بالحقِّ وعمل به فهو من المتّقين؛ ومن كذّب أو صدّق ولم يعمل فليس منهم؛ فاجمع بين التصديقِ والعمل؛ فالإيمانُ تصديقٌ وعمل؛ فحقّق تقواك بتصديقِ الحقِّ والعملِ به؛ فبذلك تكون من المتّقين الفائزين."}},{"n":34,"reflection":{"text":"«لهم ما يشاءون عند ربهم ذلك جزاء المحسنين» — للمتّقين ما يشاؤون ويشتهون عند ربّهم في الجنّة، ذلك جزاءُ المحسنين؛ ففي هذا بيانُ سعةِ نعيمِ الجنّةِ للمحسنين؛ فأحسن في عملك لتكون من المحسنين الذين لهم ما يشاؤون، فالإحسانُ سبيلُ النعيمِ الكامل، فاجعل الإحسانَ غايتك لتنال ما تشتهي في الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ في العمل رجاءَ النعيمِ الكاملِ في الجنّة."},"action":{"text":"تأمّل جزاءَ المتّقين المحسنين: لهم عند ربّهم في الجنّةِ ما يشاؤون ويشتهون ويطلبون، لا يُمنَعون شيئًا يريدونه، ذلك الجزاءُ العظيمُ جزاءُ المحسنين في أعمالهم «لهم ما يشاءون عند ربهم ذلك جزاء المحسنين»؛ ففي هذا بيانُ سعةِ نعيمِ الجنّةِ وكمالِه للمحسنين، حيث يُعطَون كلَّ ما يشتهون؛ فأحسن في عملك وعبادتك ومعاملتك لتكون من المحسنين الذين لهم ما يشاؤون في الجنّة؛ فالإحسانُ — أن تعبد الله كأنك تراه، وأن تُتقن عملك، وتُحسن إلى خلقه — سبيلُ النعيمِ الكاملِ والجزاءِ الأوفى؛ هل جزاءُ الإحسانِ إلا الإحسان؛ فمن أحسن في الدنيا أحسن الله إليه في الآخرةِ فأعطاه ما يشاء؛ فاجعل الإحسانَ غايتك في كلِّ عمل؛ فراقب إحسانك في عبادتك وأخلاقك ومعاملاتك؛ فكلّما أحسنت زاد جزاؤك؛ فللمحسنين عند ربهم ما يشاؤون؛ فاطلب هذا الجزاءَ العظيمَ بالإحسانِ في عملك كلِّه؛ فالإحسانُ أعلى مراتبِ الدين، وجزاؤه أكملُ النعيم."}},{"n":35,"reflection":{"text":"«ليكفر الله عنهم أسوأ الذي عملوا ويجزيهم أجرهم بأحسن الذي كانوا يعملون» — ليكفّر الله عنهم أسوأَ أعمالهم (يغفر سيّئاتهم) ويجزيهم أجرهم بأحسنِ أعمالهم؛ ففي هذا كرمُ الله في مغفرةِ السيّئاتِ ومضاعفةِ الحسنات؛ فأبشر بكرمِ الله الذي يغفر السيّئاتِ للتائبين ويجزي بأحسنِ العمل، فاعمل صالحًا وتب من سيّئاتك، فالله يكفّر ويجزي بالأحسن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في كرمِ الله بمغفرةِ السيّئاتِ ومضاعفةِ الحسنات."},"action":{"text":"تأمّل كرمَ الله بالمتّقين المحسنين: أعطاهم ما يشاؤون ليكفّر عنهم ويمحو أسوأَ الذي عملوا من السيّئاتِ فيغفرها لهم، ويجزيهم أجرهم بأحسنِ الذي كانوا يعملون، فيثيبهم على أحسنِ أعمالهم ويضاعفها «ليكفر الله عنهم أسوأ الذي عملوا ويجزيهم أجرهم بأحسن الذي كانوا يعملون»؛ ففي هذا كرمُ الله العظيمُ: يكفّر السيّئاتِ ويجزي بأحسنِ الحسنات؛ فأبشر بكرمِ الله الواسع؛ فهو يغفر سيّئاتِ التائبين العاملين، ويجزيهم على أحسنِ أعمالهم ويضاعفها لهم أضعافًا كثيرة؛ فمن جاء بالحسنةِ فله عشرُ أمثالها إلى أضعافٍ كثيرة؛ فاعمل صالحًا، وتب من سيّئاتك؛ فإنّ الله يكفّر السيّئاتِ بالحسناتِ والتوبة؛ إنّ الحسناتِ يذهبن السيّئات؛ فلا تيأس من مغفرةِ الله لسيّئاتك إذا تبت وأحسنت؛ وأحسن الظنَّ بكرمِ الله وفضله؛ فمن عمل صالحًا وتاب كفّر الله سيّئاته وضاعف حسناته؛ فبادر بالعملِ الصالحِ والتوبة؛ وارجُ كرمَ الله الذي يمحو السيّئاتِ ويجزي بأحسنِ العمل؛ فرحمةُ الله وكرمه أوسعُ من ذنوبك؛ فتب وأحسن، وأبشر بمغفرةِ الله وجزائه الأوفى."}}]},{"title":"كفايةُ الله لعبده، وعجزُ ما يُدعى من دونه، والتوكّل، والإنذارُ ومسؤوليةُ النفس","range":[36,41],"theme":"أنّ الله كافٍ عبده المتوكّلَ عليه ولا يضرّه تخويفُ المشركين بآلهتهم، وأنّ من يهد الله فلا مُضِلَّ له ومن يضلل فلا هادي، وإقرارُ المشركين بأنّ الله الخالقُ مع عجزِ آلهتهم عن كشفِ ضرٍّ أو إمساكِ رحمة، والأمرُ بالتوكّلِ وقولِ حسبي الله، وتهديدُ المخالفين بالعذابِ المخزي والمقيم، وأنّ الكتابَ نزل بالحقِّ فمن اهتدى فلنفسه","verses":[{"n":36,"reflection":{"text":"«أليس الله بكاف عبده ويخوفونك بالذين من دونه ومن يضلل الله فما له من هاد» — أليس الله كافيًا عبده كلَّ ما أهمّه؟ ويخوّفونك بآلهتهم أن تصيبك بسوء، ومن يضلله الله فلا هاديَ له؛ ففي هذا تقريرُ كفايةِ الله لعبده؛ فاكتفِ بالله وحده، ولا تخف من دونه شيئًا، فالله كافٍ عبده المتوكّلَ عليه، فتوكّل على الله يكفك، ولا تخف تخويفَ المخوّفين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاكتفاءُ بالله والتوكّلُ عليه، وعدمُ الخوفِ من دونه."},"action":{"text":"تأمّل تقريرَ الله لكفايته لعبده: أليس الله بكافٍ عبده المؤمنَ المتوكّلَ عليه كلَّ ما أهمّه من أمرِ دينه ودنياه؟ بلى، هو كافيه؛ والمشركون يخوّفون النبيَّ ﷺ بآلهتهم وأوثانهم أن تصيبه بسوءٍ لإنكاره عليهم، ومن يضلله الله بعدله فما له من هادٍ يهديه «أليس الله بكاف عبده ويخوفونك بالذين من دونه ومن يضلل الله فما له من هاد»؛ ففي هذا تقريرُ كفايةِ الله لعبده المتوكّلِ عليه؛ فاكتفِ بالله وحده في كلِّ أمورك؛ ولا تخف من دونه شيئًا؛ فالله كافٍ عبده الذي توكّل عليه واعتصم به؛ ومن يتوكّل على الله فهو حسبه؛ فمن كان الله كافيه فلن يضرّه أحد؛ فتوكّل على الله يكفك ما أهمّك؛ ولا تخف تخويفَ المخوّفين من الخلق؛ فإنما ذلكم الشيطانُ يخوّف أولياءه فلا تخافوهم وخافون؛ فاجعل خوفك من الله وحده؛ وثقتك بالله وحده؛ فمن اتّخذ الله كافيًا كفاه؛ فلا تلتفت إلى تهديدِ المهدّدين وتخويفِ المخوّفين؛ بل اعتصم بالله، وتوكّل عليه، واكتفِ به؛ فهو حسبك وكافيك؛ فمن كفاه الله فقد فاز، ومن اعتمد على غيره خُذِل."}},{"n":37,"reflection":{"text":"«ومن يهد الله فما له من مضل أليس الله بعزيز ذي انتقام» — ومن يهده الله فلا مُضِلَّ له، أليس الله عزيزًا غالبًا ذا انتقامٍ من أعدائه؟ ففي هذا أنّ الهدايةَ والعصمةَ بيدِ الله؛ فاطلب الهدايةَ من الله واعتصم به، فمن هداه الله لا يضلّه أحد، فاسأل الله الهدايةَ والثبات، فالمعتصمُ بالله محفوظٌ من الإضلال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدايةِ من الله والاعتصامُ به، فمن هداه لا يضلّ."},"action":{"text":"تأمّل تمامَ قدرةِ الله في الهدايةِ والإضلال: ومن يهده الله ويوفّقه للحقِّ فما له من مُضِلٍّ يقدر على إضلاله، أليس الله بعزيزٍ غالبٍ لا يُقهَر، ذي انتقامٍ شديدٍ من أعدائه الكافرين؟ «ومن يهد الله فما له من مضل أليس الله بعزيز ذي انتقام»؛ ففي هذا أنّ الهدايةَ والعصمةَ بيدِ الله وحده؛ فمن هداه الله وعصمه لم يقدر أحدٌ على إضلاله؛ فاطلب الهدايةَ من الله، واعتصم به، وتوكّل عليه؛ فمن هداه الله فلا مُضِلَّ له، ولو اجتمع عليه أهلُ الأرضِ يريدون إضلاله؛ فاسأل الله دائمًا الهدايةَ والثباتَ عليها؛ يا مقلّبَ القلوبِ ثبّت قلبي على دينك؛ فالقلوبُ بين إصبعين من أصابعِ الرحمن يقلّبها كيف يشاء؛ فالمعتصمُ بالله المهتدي بهداه محفوظٌ من الإضلالِ والفتنة؛ فاجعل اعتصامك بالله، وطلبك للهدايةِ منه؛ فهو العزيزُ الغالبُ الذي لا يُغالَب، ذو الانتقامِ من أعدائه؛ فاخشَ انتقامه، وارجُ هدايته؛ فمن اعتصم بالله هداه وعصمه وحفظه؛ فاطلب من الله أن يهديك ويثبّتك ويعصمك؛ فبهدايته لا يضرّك من أراد إضلالك."}},{"n":38,"reflection":{"text":"«ولئن سألتهم من خلق السماوات والأرض ليقولن الله قل أفرأيتم ما تدعون من دون الله إن أرادني الله بضر هل هن كاشفات ضره أو أرادني برحمة هل هن ممسكات رحمته قل حسبي الله عليه يتوكل المتوكلون» — لئن سألت المشركين من خلق السماواتِ والأرض ليقولنّ الله، قل: أفرأيتم آلهتكم، إن أرادني الله بضرٍّ هل تكشفه؟ أو أرادني برحمةٍ هل تمنعها؟ قل حسبي الله، عليه يتوكّل المتوكّلون؛ ففي هذا إبطالُ عبادةِ العاجزين وتقريرُ التوكّل؛ فتوكّل على الله وحده الذي بيده الضرُّ والنفع، فحسبك الله، فمن توكّل عليه كفاه، ولا تعلّق قلبك بعاجزٍ لا يملك ضرًّا ولا نفعًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوكّلُ على الله وحده الذي بيده الضرُّ والنفع."},"action":{"text":"تأمّل حجّةَ الله على المشركين: لئن سألتهم من خلق السماواتِ والأرضَ ليقولنّ الله — فهم مقرّون بربوبيّته — قل لهم: أفرأيتم آلهتكم التي تدعونها من دونِ الله، إن أرادني الله بضرٍّ هل تقدر أن تكشف ضرّه عني؟ أو أرادني برحمةٍ هل تقدر أن تمنعها عني؟ لا تقدر على شيءٍ من ذلك؛ قل حسبي الله وكافيّ، عليه وحده يتوكّل المتوكّلون «ولئن سألتهم من خلق السماوات والأرض ليقولن الله... قل حسبي الله عليه يتوكل المتوكلون»؛ ففي هذا إبطالُ عبادةِ الآلهةِ العاجزة، وتقريرُ التوكّلِ على الله وحده؛ فإذا كانت آلهتهم لا تملك كشفَ ضرٍّ ولا إمساكَ رحمة، فكيف تُعبَد وتُدعى؟ فالضرُّ والنفعُ بيدِ الله وحده؛ فتوكّل على الله وحده الذي بيده الضرُّ والنفعُ والخيرُ كلُّه؛ فحسبك الله وكافيك؛ فمن توكّل على الله كفاه؛ ومن يتوكّل على الله فهو حسبه؛ فلا تعلّق قلبك بعاجزٍ لا يملك لك ضرًّا ولا نفعًا؛ ولا ترجُ إلا الله، ولا تخف إلا الله؛ فاجعل توكّلك واعتمادك على الله وحده؛ فقل بلسانك وقلبك: حسبي الله؛ فمن قالها موقنًا كفاه الله كلَّ همّ؛ فالتوكّلُ على الله أصلُ الإيمان وثمرةُ التوحيد؛ فتوكّل عليه، واكتفِ به، وعلّق قلبك به وحده."}},{"n":39,"reflection":{"text":"«قل يا قوم اعملوا على مكانتكم إني عامل فسوف تعلمون» — قل يا قومِ اعملوا على حالتكم وطريقتكم، إني عاملٌ على طريقتي، فسوف تعلمون عاقبةَ الفريقين؛ ففي هذا تهديدُ المخالفين والثباتُ على الحقّ؛ فاثبت على الحقِّ واعمل به، ودع المخالفين وطريقتهم، فالعاقبةُ ستظهر، فاعمل على الحقِّ ولا يثنِك مخالفةُ الناس.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقِّ والعملُ به، وعدمُ الاكتراثِ بمخالفةِ الناس."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يقوله لقومه المعاندين: قل يا قومِ اعملوا على حالتكم وطريقتكم التي أنتم عليها من الكفرِ والعناد، إني عاملٌ على طريقتي ومنهجي من التوحيدِ والطاعة، فسوف تعلمون عاقبةَ الفريقين ومن تكون له العاقبةُ الحسنة «قل يا قوم اعملوا على مكانتكم إني عامل فسوف تعلمون»؛ ففي هذا تهديدٌ للمخالفين، وثباتٌ على الحقِّ ومفاصلةٌ لأهلِ الباطل؛ فاثبت على الحقِّ واعمل به، ولا يثنِك عنه مخالفةُ الناسِ وكثرتهم؛ ودع المخالفين وطريقتهم، وامضِ على منهجك القويم؛ فالعاقبةُ ستظهر، وسيعلم كلُّ فريقٍ نتيجةَ عمله؛ فلا تكترث بمخالفةِ الناسِ لك ما دمت على الحق؛ ولا تتنازل عن الحقِّ إرضاءً للمخالفين؛ بل قل قولةَ الحقِّ بثباتٍ: اعملوا على طريقتكم فإني عاملٌ على طريقتي؛ فاعمل على الحقِّ، واصبر عليه، وفاصل أهلَ الباطل؛ فالعاقبةُ للمتّقين؛ فمن ثبت على الحقِّ ظفر، ومن اتّبع الباطلَ خسر؛ فاثبت، واعمل، وانتظر ظهورَ العاقبة؛ فسوف تعلمون من تكون له العاقبةُ الحميدة."}},{"n":40,"reflection":{"text":"«من يأتيه عذاب يخزيه ويحل عليه عذاب مقيم» — سوف تعلمون من يأتيه عذابٌ يذلّه في الدنيا ويحلّ عليه عذابٌ دائمٌ في الآخرة؛ ففي هذا وعيدُ المخالفين بالعذابِ في الدارين؛ فاحذر أن تكون ممّن يأتيه العذابُ المخزي والمقيم، فاعمل لتنجو منه، فعاقبةُ الباطلِ الخزيُ والعذابُ الدائم، فاجتنب أسبابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من العذابِ المخزي والمقيم، والعملُ للنجاةِ منه."},"action":{"text":"تأمّل تتمّةَ الوعيدِ للمخالفين: سوف تعلمون من يأتيه في الدنيا عذابٌ يخزيه ويذلّه ويفضحه، ويحلّ عليه في الآخرةِ عذابٌ مقيمٌ دائمٌ لا ينقطع «من يأتيه عذاب يخزيه ويحل عليه عذاب مقيم»؛ ففي هذا وعيدُ المخالفين للحقِّ بالعذابِ في الدارين: خزيٌ في الدنيا وعذابٌ دائمٌ في الآخرة؛ فاحذر أن تكون ممّن يأتيه العذابُ المخزي في الدنيا والمقيمُ في الآخرة؛ فاعمل لتنجو من هذا العذاب؛ فعاقبةُ الباطلِ والكفرِ والمعاصي الخزيُ والعذابُ الدائم؛ فاجتنب أسبابَ العذابِ من الكفرِ والشركِ والمعاصي؛ والزم أسبابَ النجاةِ من الإيمانِ والتوحيدِ والطاعة؛ فمن اتّبع الحقَّ نجا من العذابِ المخزي والمقيم، ومن اتّبع الباطلَ عُذّب في الدارين؛ فاختر لنفسك سبيلَ الناجين؛ واحذر أن تكون من المعذّبين المخزيّين؛ فبادر بالإيمانِ والتوبةِ والعملِ الصالحِ قبل نزولِ العذاب؛ فالعذابُ المقيمُ لا يُطاق؛ فاعمل اليوم لتنجو منه غدًا؛ فالسعيدُ من نجا من عذابِ الله، والشقيُّ من حلّ عليه عذابه المقيم."}},{"n":41,"reflection":{"text":"«إنا أنزلنا عليك الكتاب للناس بالحق فمن اهتدى فلنفسه ومن ضل فإنما يضل عليها وما أنت عليهم بوكيل» — إنا أنزلنا عليك الكتابَ للناسِ كافّةً بالحق، فمن اهتدى فلنفسه، ومن ضلّ فإنما يضلّ على نفسه، ولست عليهم بحفيظٍ موكّلٍ بهدايتهم؛ ففي هذا بيانُ عمومِ رسالةِ القرآنِ ومسؤوليةِ كلِّ نفسٍ عن نفسها؛ فاهتدِ بالقرآنِ لنفسك، واعلم أنّ هدايتك لنفسك وضلالك عليها، فبادر بالاهتداءِ، فنفعه لك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاهتداءُ بالقرآنِ للنفس، وإدراكُ مسؤوليةِ النفسِ عن هدايتها."},"action":{"text":"تأمّل بيانَ الله لعمومِ رسالةِ القرآنِ ومسؤوليةِ الأنفس: إنا أنزلنا عليك الكتابَ للناسِ كافّةً بالحقِّ الذي لا ريبَ فيه، فمن اهتدى به فإنما هدايته لنفسه ونفعها له، ومن ضلّ عنه فإنما ضلاله على نفسه وضرره عليها، ولست يا محمدُ عليهم بوكيلٍ حفيظٍ موكّلٍ بهدايتهم، إنما عليك البلاغ «إنا أنزلنا عليك الكتاب للناس بالحق فمن اهتدى فلنفسه ومن ضل فإنما يضل عليها وما أنت عليهم بوكيل»؛ ففي هذا بيانُ أنّ القرآنَ نزل للناسِ كافّة، وأنّ كلَّ نفسٍ مسؤولةٌ عن هدايتها؛ فاهتدِ بالقرآنِ لنفسك؛ واعلم أنّ نفعَ هدايتك يعود عليك، وضررَ ضلالك يعود عليك؛ فمن اهتدى فلنفسه، ومن ضلّ فعليها؛ فلا يهتدي أحدٌ عن أحد، ولا يضلّ أحدٌ بضلالِ غيره؛ فبادر بالاهتداءِ بالقرآنِ والعملِ به؛ فإنّ نفعه لك أنت؛ ولا تظنّ أنك تنفع الله بهدايتك أو تضرّه بضلالك؛ فالله غنيٌّ عنك؛ إنما ينفعك اهتداؤك، ويضرّك ضلالك؛ فاجعل القرآنَ هاديك ودليلك؛ واعمل به لتنفع نفسك؛ فمن اهتدى بالقرآنِ سعد، ومن ضلّ عنه شقي؛ فاحرص على هدايةِ نفسك أولًا؛ فأنت المسؤولُ عنها."}}]},{"title":"توفّي الأنفسِ في الموتِ والنوم، وبطلانُ الشفعاءِ المزعومين، ونفورُ المشركين من التوحيد","range":[42,46],"theme":"أنّ الله يتوفّى الأنفسَ حين الموتِ وفي النومِ آيةً على البعث، وإبطالُ اتّخاذِ الشفعاءِ من دونِ الله وأنّ الشفاعةَ لله جميعًا وله ملكُ السماواتِ والأرض، ونفورُ قلوبِ المشركين إذا ذُكِر الله وحده واستبشارُهم بذكرِ آلهتهم، وتعليمُ الدعاءِ بأسماءِ الله فاطرِ السماواتِ عالمِ الغيبِ الذي يحكم بين عباده","verses":[{"n":42,"reflection":{"text":"«الله يتوفى الأنفس حين موتها والتي لم تمت في منامها فيمسك التي قضى عليها الموت ويرسل الأخرى إلى أجل مسمى إن في ذلك لآيات لقوم يتفكرون» — الله يقبض الأنفسَ حين الموت، والتي لم تمت يقبضها في النومِ قبضًا مؤقتًا، فيمسك التي قضى عليها الموتَ ويرسل الأخرى إلى أجلها، إنّ في ذلك لآياتٍ لقومٍ يتفكّرون؛ ففي هذا آيةُ الموتِ والنومِ على قدرةِ الله والبعث؛ فتفكّر في النومِ الذي هو موتةٌ صغرى، فمن يحييك بعد النومِ قادرٌ على بعثك بعد الموت، فاستعدّ للقاءِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في الموتِ والنومِ آيةً على البعث، والاستعدادُ للقاء."},"action":{"text":"تأمّل آيةَ الله في الأنفسِ عند الموتِ والنوم: الله يتوفّى الأنفسَ ويقبضها حين موتها قبضًا كاملًا، والتي لم تمت يقبضها في منامها قبضًا مؤقتًا، فيمسك عنده الأنفسَ التي قضى عليها الموتَ فلا يردّها، ويرسل الأنفسَ الأخرى — أنفسَ النائمين — إلى أجلِها المسمّى فتستيقظ، إنّ في ذلك لآياتٍ عظيمةً لقومٍ يتفكّرون «الله يتوفى الأنفس حين موتها والتي لم تمت في منامها فيمسك التي قضى عليها الموت ويرسل الأخرى إلى أجل مسمى إن في ذلك لآيات لقوم يتفكرون»؛ ففي هذا آيةٌ عظيمةٌ على قدرةِ الله وعلى البعث؛ فالنومُ موتةٌ صغرى، والموتُ نومةٌ كبرى؛ فتفكّر في النومِ الذي تُقبَض فيه روحك كلَّ ليلةٍ ثم تُرَدّ إليك؛ فمن يحييك بعد نومك — الذي هو أخو الموت — قادرٌ على أن يبعثك بعد موتك؛ فالذي يردّ روحك بعد النومِ يردّها بعد الموتِ للبعث؛ فاجعل من نومك واستيقاظك عبرةً وتفكّرًا في الموتِ والبعث؛ فكان النبيُّ ﷺ إذا نام قال: باسمك اللهم أموت وأحيا، وإذا استيقظ قال: الحمد لله الذي أحيانا بعد ما أماتنا وإليه النشور؛ فتذكّر عند نومك أنك قد تموت، فاستعدّ؛ وتذكّر عند استيقاظك نعمةَ الحياةِ الجديدة، فاشكر؛ فمن تفكّر في آيةِ النومِ والموتِ استعدّ للقاءِ الله؛ فالتفكّرُ في هذه الآياتِ يورث الإيمانَ بالبعثِ والاستعدادَ له."}},{"n":43,"reflection":{"text":"«أم اتخذوا من دون الله شفعاء قل أولو كانوا لا يملكون شيئا ولا يعقلون» — بل اتّخذ المشركون من دونِ الله شفعاءَ (آلهتهم) يشفعون لهم، قل: أتتّخذونهم ولو كانوا لا يملكون شيئًا ولا يعقلون؟ ففي هذا إبطالُ شفاعةِ الأصنامِ المزعومة؛ فلا تتّخذ شفيعًا من دونِ الله، ولا ترجُ شفاعةَ ما لا يملك ولا يعقل، فالشفاعةُ لله وحده، فاطلبها منه بالتوحيدِ والطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إبطالُ شفاعةِ ما دون الله، وطلبُ الشفاعةِ من الله بالتوحيد."},"action":{"text":"تأمّل إبطالَ الله لشفاعةِ الأصنام: بل اتّخذ المشركون من دونِ الله شفعاءَ من الأصنامِ والأوثانِ يزعمون أنها تشفع لهم عند الله، قل لهم منكرًا: أتتّخذونهم شفعاءَ ولو كانوا لا يملكون شيئًا من النفعِ والضرّ، ولا يعقلون ولا يفهمون؟ «أم اتخذوا من دون الله شفعاء قل أولو كانوا لا يملكون شيئا ولا يعقلون»؛ ففي هذا إبطالُ شفاعةِ الأصنامِ والمعبوداتِ الباطلة؛ فكيف تشفع جماداتٌ لا تملك شيئًا ولا تعقل؟ فلا تتّخذ شفيعًا من دونِ الله؛ ولا ترجُ شفاعةَ ما لا يملك ولا يعقل من الأصنامِ والأمواتِ والمخلوقات؛ فالشفاعةُ كلُّها لله وحده، لا تكون إلا بإذنه ورضاه؛ من ذا الذي يشفع عنده إلا بإذنه؛ فاطلب الشفاعةَ من الله بأسبابها: التوحيدِ والإخلاصِ والطاعة؛ فأسعدُ الناسِ بشفاعةِ النبيِّ ﷺ من قال لا إله إلا الله خالصًا من قلبه؛ فحقّق التوحيدَ لتنال الشفاعةَ التي يأذن بها الله؛ ولا تتعلّق بشفاعةِ من لا يملك ولا يعقل؛ فاجعل تعلّقك بالله وحده، وطلبك للشفاعةِ منه بتحقيقِ التوحيد؛ فبالتوحيدِ والإخلاصِ تُنال شفاعةُ من أذن الله له."}},{"n":44,"reflection":{"text":"«قل لله الشفاعة جميعا له ملك السماوات والأرض ثم إليه ترجعون» — قل: الشفاعةُ كلُّها لله، له ملكُ السماواتِ والأرض، ثم إليه ترجعون؛ ففي هذا تقريرُ أنّ الشفاعةَ ملكٌ لله لا تكون إلا بإذنه؛ فاطلب الشفاعةَ من الله وحده، ولا تتعلّق بغيره، فمن أراد الشفاعةَ فليتقرّب إلى مالكها بالتوحيدِ والطاعة، فالأمرُ كلُّه لله ومرجعُ الخلقِ إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بملكِ الشفاعة، وطلبُها منه بالتوحيدِ والطاعة."},"action":{"text":"تأمّل تقريرَ الله لملكِ الشفاعة: قل الشفاعةُ كلُّها لله وحده، لا يشفع أحدٌ عنده إلا بإذنه ورضاه، له ملكُ السماواتِ والأرضِ وحده، ثم إليه ترجعون جميعًا فيجازيكم بأعمالكم «قل لله الشفاعة جميعا له ملك السماوات والأرض ثم إليه ترجعون»؛ ففي هذا تقريرُ أنّ الشفاعةَ ملكٌ لله وحده، لا تقع إلا بإذنه لمن يرضى؛ فالشفاعةُ التي يثبتها القرآنُ لها شرطان: إذنُ الله للشافع، ورضاه عن المشفوعِ له؛ ولا يشفعون إلا لمن ارتضى؛ فاطلب الشفاعةَ من الله وحده مالكها؛ ولا تتعلّق بغيره من الأصنامِ والأمواتِ زاعمًا أنها تشفع لك بلا إذنِ الله؛ فمن أراد أن ينال الشفاعةَ يومَ القيامة فليتقرّب إلى الله مالكِ الشفاعةِ بالتوحيدِ والإخلاصِ والطاعة؛ فبذلك يأذن الله لمن يشاء أن يشفع له؛ فالأمرُ كلُّه لله، والملكُ كلُّه له، ومرجعُ الخلقِ إليه؛ فوحّد الله، وأخلص له، وأطعه؛ فبذلك تكون أهلًا لشفاعةِ من يأذن الله له؛ فلا تجعل بينك وبين الله وسائطَ تدعوها وترجو شفاعتها بلا إذنِ الله؛ بل تعلّق بالله وحده، مالكِ الشفاعةِ والملكِ والأمر."}},{"n":45,"reflection":{"text":"«وإذا ذكر الله وحده اشمأزت قلوب الذين لا يؤمنون بالآخرة وإذا ذكر الذين من دونه إذا هم يستبشرون» — إذا ذُكِر الله وحده في التوحيدِ نفرت وانقبضت قلوبُ الذين لا يؤمنون بالآخرة، وإذا ذُكِر آلهتهم من دونه فرحوا واستبشروا؛ ففي هذا علامةُ أهلِ الباطل: نفورهم من التوحيدِ وفرحهم بالشرك؛ فاحذر أن تنفر من التوحيدِ أو تفرح بذكرِ الباطل، بل افرح بذكرِ الله وحده، واطمئنّ للتوحيد، فقلبُ المؤمنِ يأنس بذكرِ الله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأنسُ بذكرِ الله وحده، والحذرُ من النفورِ من التوحيد."},"action":{"text":"تأمّل علامةَ أهلِ الباطلِ وأثرَ الشركِ في قلوبهم: إذا ذُكِر الله وحده في مقامِ التوحيدِ ونُفِيت الآلهةُ سواه، نفرت وانقبضت واشمأزّت قلوبُ الذين لا يؤمنون بالآخرة، لأنهم يكرهون إفرادَ الله بالعبادة؛ وإذا ذُكِر الذين من دونه من الأصنامِ والآلهةِ فرحوا واستبشروا وانشرحت صدورهم «وإذا ذكر الله وحده اشمأزت قلوب الذين لا يؤمنون بالآخرة وإذا ذكر الذين من دونه إذا هم يستبشرون»؛ ففي هذا علامةٌ فارقةٌ بين أهلِ التوحيدِ وأهلِ الشرك؛ فأهلُ الباطلِ ينفرون من التوحيدِ الخالصِ ويفرحون بذكرِ الباطلِ والشرك؛ فاحذر أن تكون فيك خصلةٌ من هذا؛ فاحذر أن تنفر من التوحيدِ الخالصِ أو من الحقِّ إذا ذُكِر؛ واحذر أن تفرح وتستبشر بذكرِ الباطلِ وأهله؛ بل افرح بذكرِ الله وحده، واطمئنّ للتوحيدِ الخالص، وانشرح صدرك له؛ فقلبُ المؤمنِ الصادقِ يأنس بذكرِ الله وحده، ويفرح بالتوحيد، ويطمئنّ إليه؛ ألا بذكرِ الله تطمئنّ القلوب؛ فراقب قلبك: هل يأنس بالتوحيدِ ويفرح به؟ أم ينفر منه ويستثقله؟ فإن وجدت في قلبك نفورًا من الحقِّ أو أنسًا بالباطلِ فعالجه؛ فاجعل فرحك وأنسك بذكرِ الله وتوحيده وطاعته؛ فذلك علامةُ الإيمانِ الصادق."}},{"n":46,"reflection":{"text":"«قل اللهم فاطر السماوات والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا فيه يختلفون» — قل: اللهم خالقَ السماواتِ والأرض، عالمَ الغيبِ والشهادة، أنت تحكم بين عبادك فيما اختلفوا فيه؛ ففي هذا تعليمُ الدعاءِ والتوسّلِ بأسماءِ الله وردِّ الأمرِ إليه؛ فادعُ الله بأسمائه وصفاته، وردَّ ما اختُلِف فيه إلى حكمِ الله، فهو وحده الحكمُ العدلُ يفصل بين المختلفين، فاطلب الحقَّ من عالمِ الغيبِ والشهادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعاءُ بأسماءِ الله، وردُّ ما اختُلِف فيه إلى حكمِ الله."},"action":{"text":"تأمّل هذا الدعاءَ العظيمَ الذي علّمه الله نبيَّه: قل اللهم يا فاطرَ السماواتِ والأرضِ وخالقهما ومبدعهما، يا عالمَ الغيبِ والشهادةِ الذي لا يخفى عليه شيء، أنت وحدك تحكم بين عبادك يومَ القيامةِ فيما كانوا فيه في الدنيا يختلفون من أمرِ الدينِ والحق «قل اللهم فاطر السماوات والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا فيه يختلفون»؛ ففي هذا تعليمُ الدعاءِ والتوسّلِ إلى الله بأسمائه وصفاته، وردُّ الأمرِ المختلَفِ فيه إليه؛ فادعُ الله وتوسّل إليه بأسمائه الحسنى وصفاته العلى؛ ولله الأسماءُ الحسنى فادعوه بها؛ فاجعل من دعائك: اللهم فاطرَ السماواتِ والأرض، عالمَ الغيبِ والشهادة، اهدني لما اختُلِف فيه من الحقِّ بإذنك؛ وردَّ ما اختُلِف فيه من أمورِ الدينِ إلى حكمِ الله وكتابِه وسنّةِ رسولِه؛ فهو وحده الحكمُ العدلُ الذي يفصل بين المختلفين بالحقّ؛ فإذا اختلف الناسُ في أمرٍ فاطلب الحقَّ من عالمِ الغيبِ والشهادة عبر وحيه؛ وما اختلفتم فيه من شيءٍ فحكمه إلى الله؛ فاجعل الله حكمك في كلِّ خلاف؛ وادعه بأسمائه أن يهديك للحقّ؛ فمن ردّ الأمرَ إلى الله ودعاه بأسمائه هداه للحقِّ وفصل له في المختلَفِ فيه."}}]},{"title":"حسرةُ الظالمين يومَ القيامة، وكفرانُ الإنسانِ عند النعمة، وأنّ الرزقَ بيدِ الله","range":[47,52],"theme":"أنّ الظالمين لو ملكوا الأرضَ ومثلها لافتدوا به من العذابِ ويبدو لهم من الله ما لم يحتسبوا وسيّئاتُ أعمالهم، وكفرانُ الإنسانِ إذ ينسب النعمةَ إلى علمه لا إلى فضلِ الله وأنها فتنة، وأنّ من قبلهم قالوها فما أغنى عنهم كسبهم فأصابهم جزاءُ سيّئاتهم، وأنّ الله يبسط الرزقَ ويقدر بحكمته آيةً للمؤمنين","verses":[{"n":47,"reflection":{"text":"«ولو أن للذين ظلموا ما في الأرض جميعا ومثله معه لافتدوا به من سوء العذاب يوم القيامة وبدا لهم من الله ما لم يكونوا يحتسبون» — لو أنّ للظالمين ما في الأرضِ جميعًا ومثله معه لافتدوا به من سوءِ العذابِ يومَ القيامة، وظهر لهم من عذابِ الله ما لم يكونوا يتوقّعون؛ ففي هذا بيانُ شدّةِ عذابِ الظالمين وحسرتهم؛ فاحذر الظلمَ الذي عاقبتُه هذا العذابُ الذي لا فداءَ منه، فاعمل اليوم قبل أن يظهر لك ما لم تحتسب، فلا فداءَ يومَ القيامة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ وعاقبتِه، والعملُ قبل يومٍ لا فداءَ فيه."},"action":{"text":"تأمّل بيانَ الله لشدّةِ حسرةِ الظالمين يومَ القيامة: لو أنّ للذين ظلموا أنفسهم بالكفرِ والمعاصي ما في الأرضِ جميعًا من الأموالِ والكنوز ومثله معه، لبذلوه كلَّه فداءً لأنفسهم من سوءِ العذابِ يومَ القيامة، ولن يُقبَل منهم؛ وظهر لهم من عذابِ الله وأهواله ما لم يكونوا يتوقّعون ولا يخطر لهم ببال «ولو أن للذين ظلموا ما في الأرض جميعا ومثله معه لافتدوا به من سوء العذاب يوم القيامة وبدا لهم من الله ما لم يكونوا يحتسبون»؛ ففي هذا بيانُ شدّةِ عذابِ الظالمين وعظمِ حسرتهم؛ فيتمنّون لو يفتدون بملءِ الأرضِ ذهبًا فلا يُقبَل؛ فاحذر الظلمَ — ظلمَ النفسِ بالشركِ والمعاصي، وظلمَ الغيرِ بالتعدّي — الذي عاقبتُه هذا العذابُ الذي لا فداءَ منه؛ فيومَ القيامةِ لا ينفع مالٌ ولا فداء؛ فلا هم يُقبَل منهم عدلٌ ولا فداء؛ فاعمل اليوم في زمنِ المهلةِ قبل أن يظهر لك من عذابِ الله ما لم تكن تحتسب؛ فبادر بالتوبةِ من الظلمِ والمعاصي؛ وأدِّ الحقوقَ لأهلها؛ واعمل صالحًا يفديك يومَ لا فداء؛ فالفداءُ يومَ القيامةِ لا يُقبَل، وإنما ينفع العملُ الصالحُ والتوبةُ في الدنيا؛ فاحذر أن تلقى الله بالظلمِ فلا تجد فداء؛ فاعمل قبل فواتِ الأوان."}},{"n":48,"reflection":{"text":"«وبدا لهم سيئات ما كسبوا وحاق بهم ما كانوا به يستهزئون» — وظهر للظالمين سيّئاتُ أعمالهم، وأحاط بهم العذابُ الذي كانوا يستهزئون به؛ ففي هذا ظهورُ عاقبةِ الأعمالِ وحلولُ ما استهزؤوا به؛ فاحذر أن تُفاجأ بسيّئاتِ أعمالك يومَ القيامة، واحذر الاستهزاءَ بوعيدِ الله، فما استهزؤوا به أحاط بهم، فخذ الوعيدَ بجدٍّ واعمل صالحًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مفاجأةِ سيّئاتِ الأعمال، ومن الاستهزاءِ بالوعيد."},"action":{"text":"تأمّل عاقبةَ الظالمين يومَ القيامة: وبدا لهم وظهر سيّئاتُ ما كسبوا من الأعمالِ القبيحةِ التي كانوا يعملونها في الدنيا، وأحاط بهم ونزل بهم العذابُ الذي كانوا يستهزئون به ويكذّبون بوقوعه «وبدا لهم سيئات ما كسبوا وحاق بهم ما كانوا به يستهزئون»؛ ففي هذا ظهورُ عاقبةِ الأعمالِ السيّئةِ لأصحابها، وحلولُ العذابِ الذي استهزؤوا به؛ فاحذر أن تُفاجأ بسيّئاتِ أعمالك يومَ القيامةِ حين تُنشَر الصحفُ وتظهر الأعمال؛ يومَ تجد كلُّ نفسٍ ما عملت من خيرٍ محضرًا وما عملت من سوء؛ فاعمل اليوم عملًا يسرّك أن تراه غدًا؛ ولا تعمل سوءًا يبدو لك ويفضحك يومَ القيامة؛ واحذر الاستهزاءَ بوعيدِ الله وآياته؛ فإنّ ما استهزأ به المستهزئون أحاط بهم ونزل بهم؛ فلا تستهزئ بشيءٍ من دينِ الله ووعيده؛ فخذ وعيدَ الله مأخذَ الجدِّ والحذر؛ واعمل صالحًا يقيك سوءَ العاقبة؛ فمن استهزأ بوعيدِ الله حاق به، ومن أخذه بجدٍّ واستعدّ له نجا؛ فبادر بالعملِ الصالحِ والتوبة؛ واحذر أن تبدو لك سيّئاتُ أعمالك يومَ لا ينفع الندم."}},{"n":49,"reflection":{"text":"«فإذا مس الإنسان ضر دعانا ثم إذا خولناه نعمة منا قال إنما أوتيته على علم بل هي فتنة ولكن أكثرهم لا يعلمون» — إذا أصاب الإنسانَ ضرٌّ دعانا، فإذا أعطيناه نعمةً قال: إنما أُوتيتُها بعلمي واستحقاقي، بل هي فتنةٌ واختبار، ولكن أكثرهم لا يعلمون؛ ففي هذا ذمُّ نسبةِ النعمةِ إلى النفسِ لا إلى الله؛ فاحذر أن تنسب النعمةَ إلى علمك وجهدك، بل انسبها إلى فضلِ الله، واعلم أنّ النعمةَ ابتلاءٌ يختبرك الله بها، فاشكرها لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"نسبةُ النعمةِ إلى فضلِ الله، وإدراكُ أنها فتنةٌ واختبار."},"action":{"text":"تأمّل ذمَّ الله للإنسانِ الجاحد: إذا مسّه ضرٌّ أو شدّةٌ دعانا وتضرّع إلينا، فإذا كشفنا ضرّه وأعطيناه نعمةً منّا قال بجحودٍ وكبر: إنما أُوتيتُ هذه النعمةَ على علمٍ منّي واستحقاقٍ وجدارة؛ بل هي فتنةٌ واختبارٌ من الله ليرى أيشكر أم يكفر، ولكن أكثرهم لا يعلمون حقيقةَ ذلك «فإذا مس الإنسان ضر دعانا ثم إذا خولناه نعمة منا قال إنما أوتيته على علم بل هي فتنة ولكن أكثرهم لا يعلمون»؛ ففي هذا ذمُّ من ينسب النعمةَ إلى نفسه وعلمه لا إلى فضلِ الله؛ فاحذر أن تنسب ما أُوتيتَه من مالٍ أو علمٍ أو جاهٍ إلى علمك وجهدك وذكائك واستحقاقك؛ كما قال قارون: إنما أوتيته على علمٍ عندي؛ بل انسب النعمَ كلَّها إلى فضلِ الله ومنّته؛ وما بكم من نعمةٍ فمن الله؛ واعلم أنّ النعمةَ ابتلاءٌ وفتنةٌ واختبارٌ يختبرك الله بها: أتشكر أم تكفر؟ أتطيع أم تعصي؟ فلنبلونّكم؛ ونبلوكم بالشرِّ والخيرِ فتنة؛ فاشكر النعمةَ لله، واستعملها في طاعته؛ ولا تغترّ بها ولا تنسبها لنفسك؛ فمن شكر النعمةَ ونسبها لله زاده، ومن كفرها ونسبها لنفسه سلبها؛ فاجعل النعمَ سببًا للشكرِ والتواضع، لا للبطرِ والكبر."}},{"n":50,"reflection":{"text":"«قد قالها الذين من قبلهم فما أغنى عنهم ما كانوا يكسبون» — قد قال هذه المقالةَ (أوتيته على علم) الذين من قبلهم كقارون، فما أغنى عنهم ما كانوا يكسبون من الأموالِ والدنيا؛ ففي هذا أنّ الدنيا لا تغني عن صاحبها شيئًا عند العذاب؛ فاعلم أنّ ما تجمعه من الدنيا لا يغني عنك عند الله، فلا تغترّ بما تكسب، بل اجعل كسبك وسيلةً لطاعةِ الله، فالدنيا لا تنفع بلا إيمانٍ وعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الدنيا لا تغني عن صاحبها، وجعلُها وسيلةً للطاعة."},"action":{"text":"اعلم أنّ هذه المقالةَ — إنما أوتيته على علمٍ واستحقاق — قد قالها الجاحدون من الأممِ قبلهم، كقارونَ وأمثاله، فما أغنى عنهم ما كانوا يكسبون من الأموالِ والكنوزِ والقوّةِ حين نزل بهم عذابُ الله «قد قالها الذين من قبلهم فما أغنى عنهم ما كانوا يكسبون»؛ ففي هذا أنّ الدنيا وما يُجمَع فيها من مالٍ وجاهٍ لا تغني عن صاحبها شيئًا عند نزولِ العذابِ وعند الله؛ فقارونُ خُسِف به وبداره الأرض، فما أغنى عنه مالُه وكنوزه؛ فاعلم أنّ ما تجمعه من الدنيا لا يغني عنك عند الله إن لم يكن معك إيمانٌ وعملٌ صالح؛ يومَ لا ينفع مالٌ ولا بنون إلا من أتى الله بقلبٍ سليم؛ فلا تغترّ بما تكسب من الدنيا وتجمع؛ ولا تظنّ أنّ مالك وجاهك يحميك من عذابِ الله؛ بل اجعل كسبك ومالك وسيلةً لطاعةِ الله والتقرّبِ إليه بالإنفاقِ والبرّ؛ فالدنيا لا تنفع صاحبها بلا إيمانٍ وعملٍ صالح؛ فما أغنى عن الجاحدين ما كسبوا؛ فاجعل همّك ما يبقى وينفع عند الله، لا ما يفنى ولا يغني؛ فمن جعل الدنيا وسيلةً للآخرةِ نفعته، ومن جعلها غايةً غرّته وخذلته."}},{"n":51,"reflection":{"text":"«فأصابهم سيئات ما كسبوا والذين ظلموا من هؤلاء سيصيبهم سيئات ما كسبوا وما هم بمعجزين» — فأصابهم جزاءُ سيّئاتِ أعمالهم، والذين ظلموا من هؤلاء (المشركين) سيصيبهم جزاءُ سيّئاتهم، وما هم بفائتين من عذابِ الله؛ ففي هذا أنّ سنّةَ الله في عقوبةِ الظالمين واحدة؛ فاحذر أن يصيبك جزاءُ سيّئاتك، واعلم أنك لن تعجز الله ولن تفوته، فاتّق الله واعمل صالحًا لتنجو، فالظالمُ لا يفوت الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من جزاءِ السيّئات، وإدراكُ أنّ الظالمَ لا يعجز الله."},"action":{"text":"اعلم أنّ الأممَ الجاحدةَ قبلهم أصابهم جزاءُ سيّئاتِ ما كسبوا من الكفرِ والمعاصي، وأنّ الذين ظلموا أنفسهم بالشركِ والمعاصي من هؤلاء المشركين المعاصرين سيصيبهم كذلك جزاءُ سيّئاتِ ما كسبوا، وما هم بمعجزين لله ولا فائتين من عقابه «فأصابهم سيئات ما كسبوا والذين ظلموا من هؤلاء سيصيبهم سيئات ما كسبوا وما هم بمعجزين»؛ ففي هذا أنّ سنّةَ الله في عقوبةِ الظالمين واحدةٌ لا تتخلّف، في الأوّلين والآخرين؛ فما أصاب الأوّلين من العقوبةِ بظلمهم سيصيب الآخرين إن سلكوا سبيلهم؛ فاحذر أن يصيبك جزاءُ سيّئاتك بالظلمِ والمعاصي؛ واعلم أنك لن تعجز الله ولن تفوته ولن تسبقه؛ فأينما كنت يدركك الموتُ والحساب؛ وما أنتم بمعجزين في الأرضِ ولا في السماء؛ فاتّق الله، واجتنب الظلمَ والمعاصي، واعمل صالحًا لتنجو من جزاءِ السيّئات؛ فالظالمُ لا يفوت الله ولا يعجزه، بل يأخذه أخذَ عزيزٍ مقتدر؛ وكذلك أخذُ ربك إذا أخذ القرى وهي ظالمة؛ فبادر بالتوبةِ من الظلمِ والمعاصي قبل أن يصيبك جزاؤها؛ فمن ظلم أُخِذ، ومن اتّقى نجا؛ فاتّق الله، ولا تظلم، تنجُ من عقوبةِ الظالمين."}},{"n":52,"reflection":{"text":"«أولم يعلموا أن الله يبسط الرزق لمن يشاء ويقدر إن في ذلك لآيات لقوم يؤمنون» — أولم يعلموا أنّ الله يوسّع الرزقَ لمن يشاء ويضيّقه على من يشاء بحكمته، إنّ في ذلك لآياتٍ لقومٍ يؤمنون؟ ففي هذا أنّ الرزقَ بيدِ الله بسطًا وقبضًا بحكمته؛ فاعلم أنّ الرزقَ بيدِ الله، فلا تغترّ بسعةِ الرزقِ ولا تيأس عند ضيقه، فسعةُ الرزقِ وضيقُه ابتلاءٌ وحكمة، فاطلب الرزقَ من الله واقنع بما قسم لك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الرزقَ بيدِ الله بسطًا وقبضًا، والقناعةُ بقسمته."},"action":{"text":"تأمّل تذكيرَ الله بأنّ الرزقَ بيده: أولم يعلم هؤلاء أنّ الله يبسط الرزقَ ويوسّعه لمن يشاء من عباده، ويقدر ويضيّقه على من يشاء، بحكمتِه وعلمِه، لا لكرامةِ من وسّع عليه ولا لهوانِ من ضيّق عليه؟ إنّ في بسطِ الرزقِ وقبضِه لآياتٍ ودلائلَ على حكمةِ الله لقومٍ يؤمنون «أولم يعلموا أن الله يبسط الرزق لمن يشاء ويقدر إن في ذلك لآيات لقوم يؤمنون»؛ ففي هذا أنّ الرزقَ بيدِ الله وحده، يبسطه ويقبضه بحكمته؛ فاعلم أنّ الرزقَ كلَّه بيدِ الله؛ فلا تغترّ بسعةِ الرزقِ فتظنّها كرامةً واستحقاقًا؛ ولا تيأس ولا تسخط عند ضيقه فتظنّه إهانة؛ فسعةُ الرزقِ وضيقُه ابتلاءٌ وحكمةٌ من الله؛ فقد يوسّع على من يحبّ ومن لا يحبّ، ويضيّق على من يحبّ ومن لا يحبّ؛ فالرزقُ ليس دليلَ محبّةٍ ولا بغض، بل هو قسمةٌ وحكمة؛ فاطلب الرزقَ من الله وحده بالأسبابِ المشروعة؛ واقنع بما قسم الله لك؛ فالقناعةُ كنزٌ لا يفنى؛ وارضَ بقضاءِ الله في رزقك؛ فمن رضي بما قسم الله له استغنى وسعد؛ ومن سخط وطمع شقي وتعب؛ فاجعل رزقك على الله، واقنع بعطائه، واشكره على ما آتاك؛ فبيدِه الرزقُ بسطًا وقبضًا بحكمته البالغة."}}]}],"coverage":{"covered":52,"total":75}};
